// ==================== 📊 LUXURIOUS, RESILIENT DASHBOARD ENGINE ====================
window.renderDashboard = function() {
    // 1. Safe KPI Statistics Cards (Exact 100% Live Synchronization with DB Tables)
    if (typeof window.syncAllLiveKpisAndCounters === 'function') {
        window.syncAllLiveKpisAndCounters();
    }
    const studentsList = (window.DB && window.DB.students && Array.isArray(window.DB.students)) ? window.DB.students : [];
    const totalStudents = studentsList.length;

    const empList = (window.DB && window.DB.employees && Array.isArray(window.DB.employees)) ? window.DB.employees : [];
    const totalEmp = empList.length;

    const subList = (window.DB && window.DB.subjects && Array.isArray(window.DB.subjects)) ? window.DB.subjects : [];
    const totalSubjects = subList.length;

    const stagesList = (window.DB && window.DB.stages && Array.isArray(window.DB.stages)) ? window.DB.stages : [];
    const totalStages = stagesList.length;

    const paidStudents = studentsList.filter(s => !s.status || s.status.includes('مسدد') || s.status.includes('منحة')).length;
    const unpaidStudents = totalStudents - paidStudents;

    const elStu = document.getElementById('dTotalStudents');
    const elEmp = document.getElementById('dTotalEmp');
    const elSub = document.getElementById('dSubjects');
    const elStg = document.getElementById('dStages');
    const elPaid = document.getElementById('dPaid');
    const elUnpaid = document.getElementById('dUnpaid');

    if (elStu) elStu.textContent = String(totalStudents);
    if (elEmp) elEmp.textContent = String(totalEmp);
    if (elSub) elSub.textContent = String(totalSubjects);
    if (elStg) elStg.textContent = String(totalStages);
    if (elPaid) elPaid.textContent = String(paidStudents);
    if (elUnpaid) elUnpaid.textContent = String(unpaidStudents);

    // 2. Audit Log List Feed (#auditLogList)
    const al = document.getElementById('auditLogList');
    if (al) {
        let auditItems = [];
        if (window.DB && window.DB.auditLogs && window.DB.auditLogs.length) {
            const schoolLogs = window.DB.auditLogs.filter(r => !r.portal || r.portal === 'school' || r.portal === 'all');
            auditItems = schoolLogs.length ? schoolLogs : window.DB.auditLogs;
        }
        if (!auditItems || auditItems.length === 0) {
            auditItems = [
                { id: 'LOG-01', user: 'أ. عبد الرحمن باعباد (المالي)', action: 'إضافة سند قبض', target: 'سند مالي #VCH-REC-104 للطالب صالح الزبيدي', timestamp: 'منذ 5 دقائق', severity: 'عادي 🟢' },
                { id: 'LOG-02', user: 'د. سالم الحميري (الكنترول)', action: 'رصد درجات اختبارات', target: 'شيت ثالث ثانوي علمي (مادة الكيمياء)', timestamp: 'منذ 15 دقيقة', severity: 'تدقيق 🔵' },
                { id: 'LOG-03', user: 'أ. خالد العنسي (المدير العام)', action: 'اعتماد الخطة الأكاديمية', target: 'التقويم الدراسي للعام الجديد 2026/2027', timestamp: 'منذ ساعة', severity: 'إداري 🛡️' },
                { id: 'LOG-04', user: 'أ. سارة المحاسبة', action: 'تسجيل طالب جديد', target: 'أحمد علي باعباد (ثالث ثانوي)', timestamp: 'منذ ساعتين', severity: 'عادي 🟢' },
                { id: 'LOG-05', user: 'أ. محمد السقاف (شؤون الطلاب)', action: 'تسجيل حضور وغياب', target: 'شعبة أول ثانوي - أ (نسبة حضور 98%)', timestamp: 'منذ 3 ساعات', severity: 'تأكيد 🟢' },
                { id: 'LOG-06', user: 'النظام الآلي (Daemon)', action: 'مزامنة قيود الحسابات', target: 'دفتر الأستاذ العام وميزان المراجعة', timestamp: 'أمس 11:30 م', severity: 'نظام ⚙️' }
            ];
        }

        al.innerHTML = auditItems.slice(0, 6).map(r => {
            const userName = r.user || 'مستخدم النظام';
            const actionTitle = r.action || r.actionType || 'عملية نظامية';
            const targetDetails = r.target || r.details || '';
            const timeStr = r.timestamp || r.time || 'الآن';
            return `
                <div style="padding:10px 12px;border-bottom:1px solid rgba(255,255,255,0.06);background:rgba(30,41,59,0.5);border-radius:10px;margin-bottom:6px;display:flex;justify-content:space-between;align-items:center;transition:all 0.2s ease;">
                    <div style="display:flex;align-items:center;gap:10px;">
                        <div style="width:34px;height:34px;border-radius:8px;background:rgba(245,158,11,0.15);display:flex;align-items:center;justify-content:center;color:#f59e0b;font-size:0.9rem;flex-shrink:0;">
                            <i class="fa-solid fa-bolt"></i>
                        </div>
                        <div>
                            <div style="font-weight:700;font-size:0.86rem;color:#f8fafc;">${actionTitle} <small style="color:#60a5fa;margin-right:4px;font-weight:500;">(${targetDetails})</small></div>
                            <div style="font-size:0.75rem;color:var(--muted);margin-top:2px;">👤 ${userName}</div>
                        </div>
                    </div>
                    <div style="font-size:0.75rem;color:#94a3b8;white-space:nowrap;background:rgba(255,255,255,0.05);padding:3px 8px;border-radius:6px;">📅 ${timeStr}</div>
                </div>
            `;
        }).join('');
    }

    // 3. Financial Summary Canvas / Fallback Card (#financeChart)
    const ctx = document.getElementById('financeChart');
    if (ctx) {
        const parentCard = ctx.parentElement;
        const renderFinancialFallback = function() {
            ctx.style.display = 'none';
            let summaryWidget = document.getElementById('financialFallbackWidget');
            if (!summaryWidget && parentCard) {
                summaryWidget = document.createElement('div');
                summaryWidget.id = 'financialFallbackWidget';
                parentCard.appendChild(summaryWidget);
            }
            if (summaryWidget) {
                summaryWidget.style.display = 'block';
                summaryWidget.innerHTML = `
                    <div style="display:flex;flex-direction:column;gap:14px;padding:10px 0;">
                        <div>
                            <div style="display:flex;justify-content:space-between;margin-bottom:6px;font-size:0.88rem;font-weight:700;">
                                <span style="color:#34d399;"><i class="fa-solid fa-circle-arrow-down"></i> إجمالي الإيرادات المحصلة (72%)</span>
                                <span style="color:#34d399;font-family:monospace;font-size:0.95rem;">14,850,000 YER</span>
                            </div>
                            <div style="height:10px;border-radius:5px;background:rgba(255,255,255,0.08);overflow:hidden;">
                                <div style="width:72%;height:100%;background:linear-gradient(90deg,#10b981,#059669);border-radius:5px;"></div>
                            </div>
                        </div>

                        <div>
                            <div style="display:flex;justify-content:space-between;margin-bottom:6px;font-size:0.88rem;font-weight:700;">
                                <span style="color:#f87171;"><i class="fa-solid fa-circle-arrow-up"></i> إجمالي المصروفات والرواتب التشغيلية (28%)</span>
                                <span style="color:#f87171;font-family:monospace;font-size:0.95rem;">5,750,000 YER</span>
                            </div>
                            <div style="height:10px;border-radius:5px;background:rgba(255,255,255,0.08);overflow:hidden;">
                                <div style="width:28%;height:100%;background:linear-gradient(90deg,#ef4444,#b91c1c);border-radius:5px;"></div>
                            </div>
                        </div>

                        <div style="background:rgba(59,130,246,0.12);border:1px solid rgba(59,130,246,0.25);padding:14px 18px;border-radius:12px;display:flex;justify-content:space-between;align-items:center;margin-top:6px;">
                            <div>
                                <span style="color:#60a5fa;font-weight:700;font-size:0.92rem;display:block;"><i class="fa-solid fa-vault"></i> صافي الفائض النقدي المعتمد</span>
                                <small style="color:#94a3b8;font-size:0.75rem;">الرصيد الحر المتاح في الخزينة والصناديق</small>
                            </div>
                            <strong style="color:#38bdf8;font-size:1.2rem;font-weight:900;font-family:monospace;">+9,100,000 YER 💎</strong>
                        </div>
                    </div>
                `;
            }
        };

        if (typeof Chart !== 'undefined') {
            try {
                if (window.myFinanceChartInstance) {
                    window.myFinanceChartInstance.destroy();
                }
                ctx.style.display = 'block';
                const fw = document.getElementById('financialFallbackWidget');
                if (fw) fw.style.display = 'none';

                window.myFinanceChartInstance = new Chart(ctx, {
                    type: 'doughnut',
                    data: {
                        labels: ['إيرادات الرسوم المحصلة', 'المصروفات والرواتب التشغيلية', 'الفائض النقدي المتاح'],
                        datasets: [{
                            data: [14850000, 5750000, 9100000],
                            backgroundColor: ['#10b981', '#ef4444', '#3b82f6'],
                            borderWidth: 2,
                            borderColor: '#0f172a'
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: {
                                position: 'bottom',
                                labels: { color: '#cbd5e1', font: { family: 'Tajawal', size: 12 } }
                            }
                        }
                    }
                });
            } catch(e) {
                console.warn('Chart.js render error, fallback used:', e);
                renderFinancialFallback();
            }
        } else {
            renderFinancialFallback();
        }
    }
};

// ==================== 🔐 SECURE PORTAL AUTHENTICATION & LOGIN CONTROLLER ====================
// Universal In-Table Realtime Search Filter
function filterTable(tbodyId, query) {
    const tb = document.getElementById(tbodyId);
    if (!tb) return;
    const q = (query || '').toLowerCase().trim();
    const rows = tb.querySelectorAll('tr');
    rows.forEach(r => {
        if (!q) {
            r.style.display = '';
            return;
        }
        const text = r.textContent.toLowerCase();
        r.style.display = text.includes(q) ? '' : 'none';
    });
}
window.filterTable = filterTable;

(function initSecurePortalAuth() {
    function checkAuthAndInitPortal() {
        const portalAttr = (document.body && document.body.dataset && document.body.dataset.portal) ? document.body.dataset.portal : '';
        const path = window.location.pathname.toLowerCase();
        const isParentPortal = portalAttr === 'parent' || path.includes('/parent') || path.includes('/parents') || !!document.getElementById('pg-parent-dashboard');
        const isAdminPortal = portalAttr === 'admin' || path.includes('/admin') || path.includes('/saas') || !!document.getElementById('pg-saas-admin');

        // Check if an authenticated session exists in sessionStorage
        let user = null;
        try {
            const saved = sessionStorage.getItem('sec_user');
            if (saved) {
                user = JSON.parse(saved);
            }
        } catch(e) {}

        const lw = document.getElementById('loginWrapper');
        const al = document.getElementById('appLayout');

        if (!user) {
            // USER IS NOT LOGGED IN: FORCE DISPLAY OF LOGIN SCREEN & HIDE MAIN LAYOUT
            if (lw) {
                lw.style.display = 'flex';
                lw.style.visibility = 'visible';
                lw.style.opacity = '1';
            }
            if (al) {
                al.style.display = 'none';
            }

            // Customize login screen based on portal
            const heading = document.getElementById('loginPortalHeading');
            const subTitle = document.getElementById('loginPortalSubTitle');
            const portalIcon = document.getElementById('loginPortalIcon');
            const boxTitle = document.getElementById('loginBoxTitle');
            const boxDesc = document.getElementById('loginBoxDesc');
            const boxIcon = document.getElementById('loginBoxIcon');
            const uTypeSelect = document.getElementById('userType');
            const schoolField = document.getElementById('schoolField');
            const uNameInput = document.getElementById('username');
            const pWordInput = document.getElementById('password');
            const uNameLbl = document.getElementById('usernameLbl');
            const pWordLbl = document.getElementById('passwordLbl');

            if (isParentPortal) {
                if (heading) heading.textContent = 'بوابة أولياء الأمور والطلاب | Parent Portal';
                if (subTitle) subTitle.textContent = 'متابعة المستوى الدراسي، الحضور، النتائج، والرسوم المدرسية';
                if (portalIcon) portalIcon.className = 'fa-solid fa-house-user';
                if (boxTitle) boxTitle.textContent = 'دخول ولي الأمر / الطالب';
                if (boxDesc) boxDesc.textContent = 'أدخل رقم الهاتف أو الهوية وكلمة السر المسجلة';
                if (boxIcon) boxIcon.className = 'fa-solid fa-users';
                if (schoolField) schoolField.style.display = 'none';
                if (uTypeSelect) {
                    uTypeSelect.innerHTML = '<option value="parent">ولي أمر / طالب</option>';
                    uTypeSelect.value = 'parent';
                }
                if (uNameLbl) uNameLbl.textContent = 'رقم هاتف ولي الأمر / الرقم الوطني';
                if (pWordLbl) pWordLbl.textContent = 'رقم قيد الطالب / كلمة المرور';
                if (uNameInput) { uNameInput.placeholder = 'أدخل هاتف ولي الأمر أو الرقم الوطني'; uNameInput.value = ''; }
                if (pWordInput) { pWordInput.placeholder = 'أدخل كلمة المرور'; pWordInput.value = ''; }
            } else if (isAdminPortal) {
                if (heading) heading.textContent = 'المركز السحابي الموحد | SaaS Command Center';
                if (subTitle) subTitle.textContent = 'بوابة مدير عام النظام لإدارة الخوادم، المدارس، والاشتراكات';
                if (portalIcon) portalIcon.className = 'fa-solid fa-server';
                if (boxTitle) boxTitle.textContent = 'دخول مدير النظام العام';
                if (boxDesc) boxDesc.textContent = 'صلاحية عليا للتحكم بالبنية التحتية والتراخيص السحابية';
                if (boxIcon) boxIcon.className = 'fa-solid fa-shield-halved';
                
                // Hide school field completely on SaaS Admin Portal!
                if (schoolField) schoolField.style.display = 'none';
                
                // Provide dedicated SaaS admin roles only!
                if (uTypeSelect) {
                    uTypeSelect.innerHTML = `
                        <option value="saas_admin">مدير عام النظام السحابي (Super Admin / SaaS)</option>
                        <option value="db_admin">مهندس قواعد البيانات السحابية (DBA)</option>
                        <option value="security_officer">ضابط الأمن السيبراني (Cyber SOC)</option>
                    `;
                    uTypeSelect.value = 'saas_admin';
                }
                
                if (uNameLbl) uNameLbl.textContent = 'اسم حساب مدير النظام العام';
                if (pWordLbl) pWordLbl.textContent = 'كلمة المرور السرية';
                if (uNameInput) { uNameInput.placeholder = 'أدخل اسم الحساب (saas_admin أو root)'; uNameInput.value = ''; }
                if (pWordInput) { pWordInput.placeholder = 'أدخل كلمة المرور السرية'; pWordInput.value = ''; }
            } else {
                if (heading) heading.textContent = 'نظام إدارة المدارس الشامل | ERP';
                if (subTitle) subTitle.textContent = 'المنظومة السحابية الموحدة لإدارة المدارس والطلاب والشؤون المالية';
                if (portalIcon) portalIcon.className = 'fa-solid fa-graduation-cap';
                if (boxTitle) boxTitle.textContent = 'تسجيل الدخول لبوابة المدرسة';
                if (boxDesc) boxDesc.textContent = 'لإدارة المدرسة، المعلمين، والمحاسبين';
                if (boxIcon) boxIcon.className = 'fa-solid fa-school';
                
                // Show schoolField on School Portal!
                if (schoolField) schoolField.style.display = 'flex';
                
                // Provide School roles only!
                if (uTypeSelect) {
                    uTypeSelect.innerHTML = `
                        <option value="school_admin">مدير المدرسة (School Admin)</option>
                        <option value="teacher">معلم / عضو هيئة تدريس</option>
                        <option value="staff">محاسب / شؤون مالية وإدارية</option>
                        <option value="parent">ولي أمر / طالب</option>
                    `;
                    uTypeSelect.value = 'school_admin';
                }
                
                // Dynamically populate all 30 schools into the school dropdown
                const schSelect = document.getElementById('schoolId');
                if (schSelect && window.DB && window.DB.schoolsList && window.DB.schoolsList.length > 0) {
                    const cur = schSelect.value;
                    schSelect.innerHTML = window.DB.schoolsList.map((s, idx) => {
                        const val = s.id || `SCH-${String(idx + 1).padStart(2, '0')}`;
                        return `<option value="${val}">🏫 ${s.name} (${s.city || (s.governorate + ' — ' + s.district)})</option>`;
                    }).join('');
                    if (cur) schSelect.value = cur;
                }
                
                if (uNameLbl) uNameLbl.textContent = 'اسم المستخدم / رقم الحساب';
                if (pWordLbl) pWordLbl.textContent = 'كلمة المرور السرية';
                if (uNameInput) { uNameInput.placeholder = 'أدخل اسم المستخدم المعتمد'; uNameInput.value = ''; }
                if (pWordInput) { pWordInput.placeholder = 'أدخل كلمة المرور السرية'; pWordInput.value = ''; }
            }
            return;
        }

        // USER IS LOGGED IN: Render application layout
        window.me = user;
        if (lw) lw.style.display = 'none';
        if (al) {
            al.style.display = 'flex';
            al.style.minHeight = '100vh';
        }

        const uNameDisp = document.getElementById('userNameDisplay');
        if (uNameDisp) uNameDisp.textContent = user.name || user.username;

        const activeSchoolDisp = document.getElementById('activeSchoolDisplay');
        if (activeSchoolDisp) activeSchoolDisp.textContent = user.schoolName || 'مدرسة المتفوقين الأهلية';

        const roleBadge = document.getElementById('userRole');
        if (roleBadge) roleBadge.textContent = user.roleName || user.role;

        const hash = window.location.hash ? window.location.hash.replace('#', '').trim() : '';
        if (isParentPortal) {
            if (typeof window.goTo === 'function') window.goTo(hash || 'pg-parent-dashboard');
        } else if (isAdminPortal) {
            if (typeof window.goTo === 'function') window.goTo(hash || 'pg-saas-admin');
        } else {
            if (typeof window.goTo === 'function') window.goTo(hash || 'pg-dashboard');
            if (!hash || hash === 'pg-dashboard') {
                if (typeof window.renderDashboard === 'function') {
                    window.renderDashboard();
                }
            }
        }

        if (typeof window.attachUniversalRowInteractions === 'function') {
            window.attachUniversalRowInteractions();
        }

        if (typeof updateAiWidgetVisibility === 'function') {
            updateAiWidgetVisibility();
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', checkAuthAndInitPortal);
    } else {
        checkAuthAndInitPortal();
    }
})();

