/**
 * ============================================================================
 * 02-AUTH-RBAC.JS - Authentication Engine, RBAC & Session Management
 * ============================================================================
 */
// =========================================================================
// 🔒 SYSTEM SECURITY: 5-FAILED-LOGIN-ATTEMPTS ACCOUNT LOCKOUT ENGINE
// =========================================================================
const MAX_ALLOWED_FAILED_ATTEMPTS = 5;
const LOCKOUT_DURATION_MS = 30 * 60 * 1000; // 30 minutes lockout

function getLockedAccounts() {
    try {
        return JSON.parse(localStorage.getItem('sys_locked_accounts') || '{}');
    } catch(e) { return {}; }
}

function getFailedLoginAttempts() {
    try {
        return JSON.parse(localStorage.getItem('sys_failed_login_attempts') || '{}');
    } catch(e) { return {}; }
}

function isAccountLocked(username) {
    const uKey = String(username || '').toLowerCase().trim();
    if (!uKey) return false;
    const locked = getLockedAccounts();
    if (!locked[uKey]) return false;
    
    const lockTime = locked[uKey].lockedAt || 0;
    if (Date.now() - lockTime > LOCKOUT_DURATION_MS) {
        delete locked[uKey];
        localStorage.setItem('sys_locked_accounts', JSON.stringify(locked));
        clearFailedLoginAttempts(uKey);
        return false;
    }
    return locked[uKey];
}

function recordFailedLoginAttempt(username) {
    const uKey = String(username || '').toLowerCase().trim();
    const attempts = getFailedLoginAttempts();
    attempts[uKey] = (attempts[uKey] || 0) + 1;
    localStorage.setItem('sys_failed_login_attempts', JSON.stringify(attempts));
    
    if (attempts[uKey] >= MAX_ALLOWED_FAILED_ATTEMPTS) {
        const locked = getLockedAccounts();
        locked[uKey] = {
            lockedAt: Date.now(),
            attempts: attempts[uKey],
            reason: 'تجاوز الحد الأقصى لمحاولات تسجيل الدخول الخاطئة (5 محاولات)'
        };
        localStorage.setItem('sys_locked_accounts', JSON.stringify(locked));
        
        // Update user status in DB if exists
        if (window.DB && window.DB.users) {
            const u = window.DB.users.find(x => String(x.username).toLowerCase() === uKey);
            if (u) u.status = 'محظور 🔒';
        }
        
        // Log critical security audit alert
        if (typeof addAudit === 'function') {
            addAudit('حظر حساب أمني 🔒', `تم تفعيل الحظر وقفل الحساب (${username}) لتجاوز 5 محاولات دخول خاطئة متتالية`, 'جدار الحماية والأمان (Firewall SOC)', 'خطر أمني (CRITICAL) 🔴');
        }
        
        return { locked: true, remaining: 0, count: attempts[uKey] };
    }
    
    return { locked: false, remaining: MAX_ALLOWED_FAILED_ATTEMPTS - attempts[uKey], count: attempts[uKey] };
}

function clearFailedLoginAttempts(username) {
    const uKey = String(username || '').toLowerCase().trim();
    const attempts = getFailedLoginAttempts();
    delete attempts[uKey];
    localStorage.setItem('sys_failed_login_attempts', JSON.stringify(attempts));
}

window.unlockAccount = function(username) {
    const uKey = String(username || '').toLowerCase().trim();
    const locked = getLockedAccounts();
    delete locked[uKey];
    localStorage.setItem('sys_locked_accounts', JSON.stringify(locked));
    clearFailedLoginAttempts(uKey);
    if (window.DB && window.DB.users) {
        const u = window.DB.users.find(x => String(x.username).toLowerCase() === uKey);
        if (u) u.status = 'نشط 🟢';
    }
    if (typeof toast === 'function') toast(`🔓 تم بنجاح فك الحظر الأمني عن الحساب (${username})!`, 0);
};
window.isAccountLocked = isAccountLocked;
window.getLockedAccounts = getLockedAccounts;

function handleLoginSubmit(e) {
    if (e && typeof e.preventDefault === 'function') e.preventDefault();
    const btn = document.getElementById('loginBtn');
    let err = document.getElementById('loginError');
    const uTypeEl = document.getElementById('userType');
    const selectedRole = uTypeEl ? uTypeEl.value : 'school_admin';
    const loginBox = document.querySelector('.login-box');
    
    if (!err) {
        err = document.createElement('div');
        err.id = 'loginError';
        err.style.cssText = 'display:none;background:rgba(239,68,68,0.15);color:#f87171;border:1px solid rgba(239,68,68,0.4);padding:12px 16px;border-radius:8px;font-size:0.9rem;font-weight:700;text-align:center;line-height:1.5;margin-bottom:15px;';
        const form = document.getElementById('loginForm');
        if (form) form.insertBefore(err, form.firstChild);
    }

    if (btn) { 
        btn.disabled = true; 
        btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> جاري التحقق...'; 
    }
    if (err) {
        err.style.display = 'none';
        err.innerHTML = '';
    }

    try {
        const uInput = document.getElementById('username');
        const pInput = document.getElementById('password');
        let uName = (uInput ? uInput.value : '').trim();
        let pWord = (pInput ? pInput.value : '').trim();

        if (!uName) {
            if (uInput) uInput.focus();
            throw new Error('⚠️ يرجى إدخال اسم المستخدم أو رقم الحساب!');
        }

        if (!pWord) {
            if (pInput) pInput.focus();
            throw new Error('⚠️ يرجى إدخال كلمة المرور!');
        }

        // Normalize Arabic digits in password (e.g. ١٢٣ -> 123)
        const normalizedPw = pWord.replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));

        const portalAttr = (document.body && document.body.dataset && document.body.dataset.portal) ? document.body.dataset.portal : '';
        const path = window.location.pathname.toLowerCase();
        const isAdminPortal = portalAttr === 'admin' || path.includes('/admin') || path.includes('/saas') || !!document.getElementById('pg-saas-admin');
        const isParentPortal = portalAttr === 'parent' || path.includes('/parent') || path.includes('/parents') || !!document.getElementById('pg-parent-dashboard');

        let allUsers = (window.DB && window.DB.users && Array.isArray(window.DB.users) && window.DB.users.length > 0) ? [...window.DB.users] : [];
        
        // Standard system accounts
        const defaultAccounts = [
            { id: 'usr_saas', username: 'saas_admin', password: '123', name: 'م. عبد الله الشامي (مدير النظام العام)', role: 'saas_admin', roleName: 'مدير عام النظام (Super Admin)', status: 'نشط' },
            { id: 'usr_root', username: 'root', password: '123', name: 'م. حسام الدين (مدير النظام)', role: 'saas_admin', roleName: 'مدير عام النظام (Super Admin)', status: 'نشط' },
            { id: 'usr_dba', username: 'db_admin', password: '123', name: 'م. طارق المعمري (مهندس قواعد البيانات)', role: 'db_admin', roleName: 'مهندس البنية وقواعد البيانات', status: 'نشط' },
            { id: 'usr_soc', username: 'soc_guardian', password: '123', name: 'الرائد صقر الحميري (Cyber Guardian AI)', role: 'security_officer', roleName: 'ضابط الأمن السيبراني', status: 'نشط' },
            { id: 'usr_soc_alias', username: 'soc', password: '123', name: 'الرائد صقر الحميري (Cyber Guardian AI)', role: 'security_officer', roleName: 'ضابط الأمن السيبراني', status: 'نشط' },
            { id: 'usr_soc_alias2', username: 'cyber', password: '123', name: 'الرائد صقر الحميري (Cyber Guardian AI)', role: 'security_officer', roleName: 'ضابط الأمن السيبراني', status: 'نشط' },
            { id: 'usr_1', username: 'admin', password: '123', name: isAdminPortal ? 'م. عبد الله الشامي (مدير النظام العام)' : 'أ. خالد العنسي (المدير العام)', role: isAdminPortal ? 'saas_admin' : 'school_admin', roleName: isAdminPortal ? 'مدير عام النظام (Super Admin)' : 'مدير المدرسة', status: 'نشط' },
            { id: 'usr_2', username: 'teacher', password: '123', name: 'أ. عبد الرحمن باعباد', role: 'teacher', roleName: 'معلم', status: 'نشط' },
            { id: 'usr_3', username: 'staff', password: '123', name: 'أ. سارة المحاسبة', role: 'staff', roleName: 'محاسب وموظف', status: 'نشط' },
            { id: 'usr_4', username: 'parent', password: '123', name: 'عبد الله أحمد الأهدل (ولي أمر)', role: 'parent', roleName: 'ولي أمر', status: 'نشط' }
        ];

        // Also add all 30 school principals if not already populated
        for (let sIdx = 1; sIdx <= 30; sIdx++) {
            const pCode = `admin_sch_${String(sIdx).padStart(2, '0')}`;
            if (!defaultAccounts.some(a => a.username === pCode)) {
                defaultAccounts.push({
                    id: `usr_sch_${sIdx}`,
                    username: pCode,
                    password: '123',
                    name: `مدير مدرسة ${sIdx}`,
                    role: 'school_admin',
                    roleName: 'مدير المدرسة',
                    schoolId: sIdx,
                    status: 'نشط'
                });
            }
        }

        defaultAccounts.forEach(defAcc => {
            if (!allUsers.some(u => String(u.username).toLowerCase() === defAcc.username.toLowerCase())) {
                allUsers.push(defAcc);
            }
        });

        const uLower = uName.toLowerCase();
        // Match user by username, nationalId, or id
        let userMatch = allUsers.find(u => 
            String(u.username).toLowerCase() === uLower || 
            String(u.id).toLowerCase() === uLower || 
            String(u.nationalId) === uName ||
            String(u.phone) === uName
        );

        // Fallback matching
        if (!userMatch) {
            if (isAdminPortal) {
                // Any admin login on SaaS portal maps to SaaS admin
                userMatch = defaultAccounts.find(a => a.username === 'saas_admin');
            } else if (isParentPortal) {
                userMatch = defaultAccounts.find(a => a.username === 'parent');
            } else if (uLower.includes('admin') || uLower.includes('مدير')) {
                userMatch = defaultAccounts.find(a => a.username === 'admin');
            } else if (uLower.includes('teach') || uLower.includes('معلم')) {
                userMatch = defaultAccounts.find(a => a.username === 'teacher');
            } else if (uLower.includes('staff') || uLower.includes('محاسب')) {
                userMatch = defaultAccounts.find(a => a.username === 'staff');
            }
        }

        // 1. Check if account is locked prior to authentication
        const lockInfo = isAccountLocked(uName);
        if (lockInfo) {
            const minsLeft = Math.max(1, Math.ceil((LOCKOUT_DURATION_MS - (Date.now() - lockInfo.lockedAt)) / 60000));
            throw new Error(`🚫 تم حظر وقفل هذا الحساب (${uName}) أمنياً لتجاوز أكثر من 5 محاولات دخول خاطئة متتالية!\nالحساب محمي من هجمات التخمين. يرجى الانتظار (${minsLeft} دقيقة) أو التواصل مع مسؤول النظام لفك الحظر.`);
        }

        if (!userMatch) {
            if (uInput) uInput.focus();
            const att = recordFailedLoginAttempt(uName);
            if (att.locked) {
                throw new Error(`🚫 تم حظر وقفل الحساب (${uName}) نهائياً لتجاوز الحد الأقصى لمحاولات الدخول الخاطئة (5 محاولات)!\nيرجى التواصل مع مسؤول النظام.`);
            } else {
                throw new Error(`❌ اسم المستخدم أو الرقم (${uName}) غير مسجل!\nتبقّت لك (${att.remaining}) محاولات من أصل 5 محاولات.`);
            }
        }

        // Accept registered password or standard passwords (123, admin, root, etc.)
        const isPwValid = (userMatch.password === pWord) || 
                          (userMatch.password === normalizedPw) || 
                          (pWord === '123') || 
                          (normalizedPw === '123') || 
                          (pWord.toLowerCase() === 'admin') || 
                          (pWord.toLowerCase() === 'root') || 
                          (pWord.toLowerCase() === 'admin123') || 
                          (pWord.toLowerCase() === 'password') || 
                          (pWord.toLowerCase() === userMatch.username.toLowerCase());

        if (!isPwValid) {
            if (pInput) pInput.focus();
            const att = recordFailedLoginAttempt(uName);
            if (att.locked) {
                throw new Error(`🚫 تم حظر وقفل هذا الحساب (${uName}) نهائياً لتجاوز الحد الأقصى لمحاولات الدخول الخاطئة (5 محاولات)!\nتم تفعيل إجراءات الحماية السيبرانية وتوثيق الواقعة في سجل التدقيق الأمني.`);
            } else {
                throw new Error(`❌ كلمة المرور غير صحيحة! كلمة المرور الافتراضية هي: 123\n⚠️ تحذير أمني: تبقّت لك (${att.remaining}) محاولات من أصل 5 محاولات قبل حظر وقفل الحساب.`);
            }
        }

        // On successful password validation, reset failed attempts
        clearFailedLoginAttempts(uName);

        // Portal School Context Setup
        const rawSchoolVal = document.getElementById('schoolId')?.value || 'SCH-01';
        const rawSchoolNum = parseInt(String(rawSchoolVal).replace(/\D/g, '')) || 1;
        const selectedSchoolId = isAdminPortal ? 'ALL' : rawSchoolNum;
        const selectedSchoolCode = isAdminPortal ? 'ALL' : (String(rawSchoolVal).startsWith('SCH-') ? rawSchoolVal : `SCH-${String(rawSchoolNum).padStart(2, '0')}`);
        const selectedSchoolName = isAdminPortal ? 'المركز السحابي الموحد (كافة المدارس الـ 30)' : (document.getElementById('schoolId')?.options[document.getElementById('schoolId')?.selectedIndex]?.text || 'مدرسة المتفوقين الأهلية');

        window.currentSchoolId = (selectedSchoolId === 'ALL') ? 1 : selectedSchoolId;
        window.currentSchoolCode = selectedSchoolCode;

        // Determine Appropriate Role based on active portal
        let finalRole = userMatch.role || selectedRole;
        if (isAdminPortal) {
            finalRole = (userMatch.role === 'db_admin' || userMatch.role === 'security_officer') ? userMatch.role : 'saas_admin';
        } else if (isParentPortal) {
            finalRole = 'parent';
        }

        const roleNames = {
            'saas_admin': 'مدير عام النظام السحابي (Super Admin)',
            'db_admin': 'مهندس قواعد البيانات السحابية (DBA)',
            'security_officer': 'ضابط الأمن السيبراني (Cyber SOC)',
            'school_admin': 'مدير المدرسة (School Admin)',
            'teacher': 'معلم / هيئة تدريس',
            'staff': 'محاسب / شؤون إدارية',
            'parent': 'ولي أمر / طالب'
        };

        const token = 'sec_token_' + Date.now() + '_' + Math.random().toString(36).substring(2, 9);
        const me = {
            id: userMatch.id,
            username: userMatch.username,
            name: userMatch.name || userMatch.username,
            role: finalRole,
            roleName: roleNames[finalRole] || userMatch.roleName || finalRole,
            schoolId: selectedSchoolId,
            schoolCode: selectedSchoolCode,
            schoolName: selectedSchoolName,
            permissions: userMatch.permissions || { students: true, finance: true, accounting: true, control: true }
        };
        window.me = me;

        const disp = document.getElementById('activeSchoolDisplay');
        if (disp) disp.textContent = selectedSchoolName;

        try { 
            sessionStorage.setItem('sec_session_token', token); 
            sessionStorage.setItem('sec_user', JSON.stringify(me)); 
            localStorage.setItem('sec_user_session', JSON.stringify(me));
        } catch(e){}

        // Transition UI from login screen to App Layout
        const lw = document.getElementById('loginWrapper');
        const al = document.getElementById('appLayout');
        const sb = document.getElementById('sidebar');

        if (lw) lw.style.display = 'none';
        if (al) {
            al.style.display = 'flex';
            al.style.minHeight = '100vh';
        }
        if (sb) {
            sb.style.display = 'flex';
            sb.style.visibility = 'visible';
            sb.style.opacity = '1';
        }

        const uNameDisp = document.getElementById('userNameDisplay');
        if (uNameDisp) uNameDisp.textContent = me.name || me.username;

        const roleBadge = document.getElementById('userRole');
        if (roleBadge) roleBadge.textContent = me.roleName || me.role;

        if (typeof addAudit === 'function') addAudit('تسجيل دخول ناجح', `تم تسجيل الدخول بنجاح للمستخدم: ${me.name}`);
        if (typeof toast === 'function') toast(`👋 مرحباً بك ${me.name}! تم تسجيل الدخول بنجاح 🟢`);
        if (typeof updateAiWidgetVisibility === 'function') updateAiWidgetVisibility();

        // Navigate to appropriate page
        requestAnimationFrame(() => {
            setTimeout(() => {
                if (me.role === 'parent' || window.location.pathname.includes('/parent')) {
                    if (typeof goTo === 'function') goTo('pg-parent-dashboard');
                } else if (me.role === 'saas_admin' || me.role === 'db_admin' || me.role === 'security_officer' || window.location.pathname.includes('/admin') || window.location.pathname.includes('/saas')) {
                    if (typeof goTo === 'function') goTo('pg-saas-admin');
                } else {
                    if (typeof goTo === 'function') goTo('pg-dashboard');
                }
            }, 30);
        });

    } catch (errEx) {
        const errorMsg = errEx.message || 'خطأ أثناء التحقق من بيانات تسجيل الدخول';
        
        if (err) { 
            err.innerHTML = `<i class="fa-solid fa-triangle-exclamation" style="margin-left:6px;"></i> ${errorMsg}`; 
            err.style.display = 'block'; 
        }

        if (typeof toast === 'function') {
            toast(errorMsg, 1);
        }

        if (loginBox) {
            loginBox.style.transition = 'transform 0.1s ease';
            loginBox.style.transform = 'translateX(-10px)';
            setTimeout(() => { loginBox.style.transform = 'translateX(10px)'; }, 100);
            setTimeout(() => { loginBox.style.transform = 'translateX(-6px)'; }, 200);
            setTimeout(() => { loginBox.style.transform = 'translateX(6px)'; }, 300);
            setTimeout(() => { loginBox.style.transform = 'translateX(0)'; }, 400);
        }

    } finally {
        if (btn) { 
            btn.disabled = false; 
            btn.innerHTML = '<i class="fa-solid fa-right-to-bracket"></i> تسجيل الدخول للمنظومة'; 
        }
    }
}
window.handleLoginSubmit = handleLoginSubmit;


function quickFillLogin(user, pass, role) {
    const uInput = document.getElementById('username');
    const pInput = document.getElementById('password');
    const rSelect = document.getElementById('userType');
    if (uInput) uInput.value = user;
    if (pInput) pInput.value = pass;
    if (rSelect && role) {
        rSelect.value = role;
        if (typeof rSelect.onchange === 'function') rSelect.onchange();
    }
    const err = document.getElementById('loginError');
    if (err) err.style.display = 'none';
    if (typeof toast === 'function') toast('⚡ تم تعبئة بيانات الحساب: ' + user);
}
window.quickFillLogin = quickFillLogin;


function applyRBACPermissions(user) {
    if (!user) return;
    const sidebar = document.getElementById('sidebar');
    if (!sidebar) return;

    if (user.role === 'parent') {
        const links = sidebar.querySelectorAll('.nav-links > li');
        links.forEach(li => {
            const hasParent = li.querySelector('a[onclick*="pg-parent"]') || li.querySelector('a[onclick*="pg-student-"]');
            if (!hasParent) li.style.display = 'none';
        });
    }
}
window.applyRBACPermissions = applyRBACPermissions;

function togglePasswordVisibility() {
    const passInput = document.getElementById('password');
    const icon = document.getElementById('togglePassword');
    if (!passInput || !icon) return;
    if (passInput.type === 'password') {
        passInput.type = 'text';
        icon.classList.remove('fa-eye');
        icon.classList.add('fa-eye-slash');
    } else {
        passInput.type = 'password';
        icon.classList.remove('fa-eye-slash');
        icon.classList.add('fa-eye');
    }
}
window.togglePasswordVisibility = togglePasswordVisibility;

function logout() {
    try {
        sessionStorage.clear();
        localStorage.removeItem('sec_user_session');
    } catch(e){}
    const lw = document.getElementById('loginWrapper');
    const al = document.getElementById('appLayout');
    if (lw) lw.style.display = 'flex';
    if (al) al.style.display = 'none';
    toast('👋 تم تسجيل الخروج بأمان');
    if (typeof updateAiWidgetVisibility === 'function') updateAiWidgetVisibility();
}
window.logout = logout;


