window.toggleTreeNode = function(nodeId) {
    const el = document.getElementById(nodeId);
    const icon = document.getElementById('icon-' + nodeId);
    if (!el) return;
    if (el.style.display === 'none') {
        el.style.display = 'block';
        if (icon) icon.className = 'fa-solid fa-chevron-down';
    } else {
        el.style.display = 'none';
        if (icon) icon.className = 'fa-solid fa-chevron-left';
    }
};

window.toggleAllTreeNodes = function(expand) {
    document.querySelectorAll('.tree-branch-content').forEach(el => {
        el.style.display = expand ? 'block' : 'none';
    });
    document.querySelectorAll('.tree-toggle-icon').forEach(icon => {
        icon.className = expand ? 'fa-solid fa-chevron-down tree-toggle-icon' : 'fa-solid fa-chevron-left tree-toggle-icon';
    });
};

