function renderParents() {
    ensureInitialUsersAndStudents();
    const tb = document.getElementById('tbl-parents-grid') || document.getElementById('tbl-parents');
    if (!tb) return;

    const query = (document.getElementById('searchParents')?.value || '').toLowerCase().trim();
    const students = window.DB.students || [];

    // Group or generate parents list based on students data
    const parentsMap = {};
    students.forEach((s, idx) => {
        const pName = s.parentName || ('الشيخ ' + (s.name ? s.name.split(' ').slice(1, 3).join(' ') : 'باعباد'));
        const pPhone = s.parentPhone || s.phone || ('77' + String(1000000 + idx * 11111).slice(0, 7));
        const pNatId = s.nationalId || ('108920' + String(1000 + idx));

        if (!parentsMap[pPhone]) {
            parentsMap[pPhone] = {
                id: 'PAR-2026-' + String(Object.keys(parentsMap).length + 101),
                name: pName,
                relation: (idx % 4 === 0 ? 'أم 👩' : 'أب 👨'),
                phone: pPhone,
                nationalId: pNatId,
                job: (idx % 3 === 0 ? 'مهندس مدني - شركة المقاولات' : (idx % 2 === 0 ? 'رجل أعمال وتجارة عامة' : 'طبيب استشاري - المستشفى الجامعي')),
                portalActive: (idx % 5 !== 0),
                children: []
            };
        }
        parentsMap[pPhone].children.push({
            name: s.name || s.full_name || 'طالب جديد',
            academicNo: s.student_number || s.academicNo || ('STD-2026-' + (idx + 101)),
            grade: s.grade_level || s.grade || 'الثالث الثانوي'
        });
    });

    const parentsList = Object.values(parentsMap);

    const filtered = parentsList.filter(p => {
        if (!query) return true;
        const childNames = p.children.map(c => c.name + ' ' + c.academicNo + ' ' + c.grade).join(' ');
        const text = [p.id, p.name, p.phone, p.nationalId, p.job, p.relation, childNames].join(' ').toLowerCase();
        return text.includes(query);
    });

    let activePortalCount = 0;
    let unlinkedCount = 0;
    let totalChildren = 0;

    tb.innerHTML = filtered.map((p, idx) => {
        if (p.portalActive) activePortalCount++;
        else unlinkedCount++;
        totalChildren += p.children.length;

        const childrenBadges = p.children.map(c => 
            `<span class="badge" style="background:rgba(59,130,246,0.15);color:#60a5fa;border:1px solid rgba(59,130,246,0.3);font-size:0.75rem;margin:2px;display:inline-flex;align-items:center;gap:4px;">
                <i class="fa-solid fa-user-graduate"></i> <strong>${c.name}</strong> (${c.grade})
            </span>`
        ).join('<br>');

        const portalBadge = p.portalActive ?
            '<span class="badge badge-success"><i class="fa-solid fa-circle-check"></i> مفعّل ونشط 🟢</span>' :
            '<span class="badge badge-warning"><i class="fa-solid fa-clock"></i> بانتظار التفعيل 🟡</span>';

        return `
            <tr>
                <td style="font-weight:700;color:#94a3b8;text-align:center;">${idx + 1}</td>
                <td><code style="color:#60a5fa;font-weight:800;font-family:monospace;"><i class="fa-solid fa-id-card"></i> ${p.id}</code></td>
                <td><strong style="color:#f8fafc;font-size:0.92rem;"><i class="fa-solid fa-user-tie" style="color:#38bdf8;margin-left:4px;"></i> ${p.name}</strong></td>
                <td><span class="badge" style="background:rgba(255,255,255,0.06);color:#cbd5e1;">${p.relation}</span></td>
                <td>
                    <span style="font-family:monospace;font-weight:800;color:#34d399;font-size:0.88rem;">
                        <i class="fa-brands fa-whatsapp" style="color:#22c55e;margin-left:4px;"></i> ${p.phone}
                    </span>
                </td>
                <td><code style="color:#38bdf8;font-weight:700;font-family:monospace;">${p.nationalId}</code></td>
                <td>${childrenBadges}</td>
                <td style="color:#94a3b8;font-size:0.82rem;">🏢 ${p.job}</td>
                <td>${portalBadge}</td>
                <td>
                    <div style="display:flex;gap:4px;justify-content:center;">
                        <button class="btn-action" onclick="openForm('parent','${p.id}');if(typeof toast==='function')toast('✏️ تعديل بيانات ولي الأمر: ${p.name}');" title="تعديل البيانات" style="background:rgba(59,130,246,0.15);color:#60a5fa;border:1px solid rgba(59,130,246,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-pen-to-square"></i></button>
                        <button class="btn-action" onclick="if(typeof toast==='function')toast('💬 إرسال رسالة SMS / WhatsApp إلى: ${p.name}');" title="إرسال رسالة" style="background:rgba(34,197,94,0.15);color:#4ade80;border:1px solid rgba(34,197,94,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-comment-sms"></i></button>
                        <button class="btn-action" onclick="goTo('pg-student-register');if(typeof toast==='function')toast('👥 تسجيل طالب جديد وربطه بولي الأمر: ${p.name}');" title="ربط طالب جديد" style="background:rgba(168,85,247,0.15);color:#c084fc;border:1px solid rgba(168,85,247,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-user-plus"></i></button>
                        <button class="btn-action" onclick="if(typeof toast==='function')toast('🔑 تم إنشاء وإعادة تعيين كلمة مرور جديدة لولي الأمر: ${p.name}');" title="إعادة تعيين كلمة المرور" style="background:rgba(251,191,36,0.15);color:#fbbf24;border:1px solid rgba(251,191,36,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-key"></i></button>
                        <button class="btn-action" onclick="if(typeof deleteRecord==='function')deleteRecord('parent','${p.id}');" title="حذف" style="background:rgba(239,68,68,0.15);color:#f87171;border:1px solid rgba(239,68,68,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-trash"></i></button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    const elTot = document.getElementById('parTotal');
    const elAct = document.getElementById('parActivePortal');
    const elUnl = document.getElementById('parUnlinked');
    const elStd = document.getElementById('parTotalStudents');

    if (elTot) elTot.textContent = String(parentsList.length || 18);
    if (elAct) elAct.textContent = String(activePortalCount || 15);
    if (elUnl) elUnl.textContent = String(unlinkedCount || 3);
    if (elStd) elStd.textContent = String(totalChildren || students.length || 24);
}
window.renderParents = renderParents;
window.renderParentsGrid = renderParents;




