function renderStudentDocs() {
    ensureInitialUsersAndStudents();
    const tb = document.getElementById('tbl-student-docs-grid') || document.getElementById('tbl-student-docs');
    if (!tb) return;

    const query = (document.getElementById('searchStudentDocs')?.value || '').toLowerCase().trim();
    const students = window.DB.students || [];

    const filtered = students.filter(s => {
        if (!query) return true;
        const text = [s.id, s.name, s.full_name, s.student_number, s.academicNo, s.nationalId, s.parentName, s.parentPhone, s.phone, s.grade, s.section, s.grade_level].join(' ').toLowerCase();
        return text.includes(query);
    });

    let completeCount = 0;
    let pendingCount = 0;
    let missingCount = 0;
    let totalFilesCount = 0;

    tb.innerHTML = filtered.map((s, idx) => {
        const studentName = s.name || s.full_name || ('طالب ' + (idx + 1));
        const academicNo = s.student_number || s.academicNo || s.id || ('STD-2026-' + String(idx + 101));
        const gr = s.grade_level || s.grade || (idx % 2 === 0 ? 'الثالث الثانوي - علمي 1' : 'التاسع أساسي - أ');

        // Deterministic document mock status
        let birthCert = '<span class="badge badge-success"><i class="fa-solid fa-file-pdf"></i> مرفقة 📄</span>';
        let transferCert = '<span class="badge badge-success"><i class="fa-solid fa-file-circle-check"></i> معتمدة 📜</span>';
        let personalPhotos = '<span class="badge badge-success"><i class="fa-solid fa-image"></i> مكتملة (4) 🖼️</span>';
        let medicalReport = '<span class="badge badge-success"><i class="fa-solid fa-heart-pulse"></i> لائق طبياً 🩺</span>';
        let percentage = 100;
        let pColor = '#10b981';

        if (idx % 4 === 1) {
            medicalReport = '<span class="badge badge-warning"><i class="fa-solid fa-clock"></i> مطلوب ⏳</span>';
            percentage = 75;
            pColor = '#f59e0b';
            pendingCount++;
            totalFilesCount += 3;
        } else if (idx % 4 === 2) {
            transferCert = '<span class="badge badge-warning"><i class="fa-solid fa-clock"></i> قيد المتابعة ⏳</span>';
            personalPhotos = '<span class="badge badge-danger"><i class="fa-solid fa-triangle-exclamation"></i> ناقصة (1) ⚠️</span>';
            percentage = 50;
            pColor = '#f59e0b';
            pendingCount++;
            totalFilesCount += 2;
        } else if (idx % 4 === 3 && idx > 8) {
            birthCert = '<span class="badge badge-danger"><i class="fa-solid fa-xmark"></i> غير مرفقة ❌</span>';
            transferCert = '<span class="badge badge-danger"><i class="fa-solid fa-xmark"></i> غير مرفقة ❌</span>';
            personalPhotos = '<span class="badge badge-danger"><i class="fa-solid fa-xmark"></i> غير مرفقة ❌</span>';
            medicalReport = '<span class="badge badge-danger"><i class="fa-solid fa-xmark"></i> غير مرفقة ❌</span>';
            percentage = 0;
            pColor = '#ef4444';
            missingCount++;
        } else {
            completeCount++;
            totalFilesCount += 4;
        }

        return `
            <tr>
                <td style="font-weight:700;color:#94a3b8;text-align:center;">${idx + 1}</td>
                <td><code style="color:#60a5fa;font-weight:800;font-family:monospace;"><i class="fa-solid fa-id-badge"></i> ${academicNo}</code></td>
                <td><strong style="color:#f8fafc;font-size:0.92rem;">👤 ${studentName}</strong></td>
                <td style="font-weight:700;color:#a78bfa;"><i class="fa-solid fa-layer-group"></i> ${gr}</td>
                <td>${birthCert}</td>
                <td>${transferCert}</td>
                <td>${personalPhotos}</td>
                <td>${medicalReport}</td>
                <td style="text-align:center;">
                    <div style="display:flex;align-items:center;gap:6px;justify-content:center;">
                        <div style="flex:1;max-width:60px;background:rgba(255,255,255,0.08);height:6px;border-radius:3px;overflow:hidden;">
                            <div style="width:${percentage}%;background:${pColor};height:100%;"></div>
                        </div>
                        <strong style="color:${pColor};font-size:0.8rem;font-family:monospace;">${percentage}%</strong>
                    </div>
                </td>
                <td>
                    <div style="display:flex;gap:4px;justify-content:center;">
                        <button class="btn-action" onclick="if(typeof toast==='function')toast('👁️ معاينة الأرشيف الرقمي للطالب: ${studentName}');" title="معاينة الأرشيف" style="background:rgba(59,130,246,0.15);color:#60a5fa;border:1px solid rgba(59,130,246,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-folder-open"></i></button>
                        <button class="btn-action" onclick="openForm('student_doc');if(typeof toast==='function')toast('📤 رفع وثيقة جديدة لـ ${studentName}');" title="رفع وثيقة جديدة" style="background:rgba(16,185,129,0.15);color:#34d399;border:1px solid rgba(16,185,129,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-cloud-arrow-up"></i></button>
                        <button class="btn-action" onclick="if(typeof toast==='function')toast('💬 إرسال تذكير بنواقص الوثائق لولي أمر: ${studentName}');" title="إرسال إشعار لولي الأمر" style="background:rgba(251,191,36,0.15);color:#fbbf24;border:1px solid rgba(251,191,36,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-paper-plane"></i></button>
                        <button class="btn-action" onclick="if(typeof toast==='function')toast('🖨️ طباعة استمارة القبول لـ ${studentName}');" title="طباعة استمارة القبول" style="background:rgba(168,85,247,0.15);color:#c084fc;border:1px solid rgba(168,85,247,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-print"></i></button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    const elTot = document.getElementById('docTotalFiles');
    const elCom = document.getElementById('docComplete');
    const elPen = document.getElementById('docPending');
    const elMis = document.getElementById('docMissing');

    if (elTot) elTot.textContent = String(totalFilesCount || (students.length * 4) || 96);
    if (elCom) elCom.textContent = String(completeCount || Math.round(students.length * 0.6) || 16);
    if (elPen) elPen.textContent = String(pendingCount || Math.round(students.length * 0.3) || 7);
    if (elMis) elMis.textContent = String(missingCount || 1);
}
window.renderStudentDocs = renderStudentDocs;




// ============================================================================
// 🔀 STUDENT SECTION DISTRIBUTION ENGINE
// ============================================================================

window.autoDistributeStudents = function() {
    const students = window.DB.students || [];
    let count = 0;
    students.forEach((s, idx) => {
        if (!s.section || s.section.includes('قيد')) {
            s.section = idx % 2 === 0 ? 'علمي 1' : 'علمي 2';
            count++;
        }
    });
    if (typeof toast === 'function') toast(`⚡ تم التوزيع الآلي لـ (${count || 4}) طلاب على الشعب بتوازن تام 🟢`);
    renderSectionDistribution();
};

window.updateStudentSection = function(studentId, newSection) {
    const students = window.DB.students || [];
    const s = students.find(x => String(x.id) === String(studentId));
    if (s) {
        s.section = newSection;
        if (typeof toast === 'function') toast(`🔄 تم نقل الطالب [${s.name || s.full_name}] إلى [${newSection}] بنجاح`);
    }
};

function renderSectionDistribution() {
    ensureInitialUsersAndStudents();
    const tb = document.getElementById('tbl-section-dist-grid') || document.getElementById('tbl-section-distribution');
    if (!tb) return;

    const query = (document.getElementById('searchSectionDist')?.value || '').toLowerCase().trim();
    const gradeFilter = (document.getElementById('filterDistGrade')?.value || '').trim();
    const students = window.DB.students || [];

    const filtered = students.filter(s => {
        const text = [s.id, s.name, s.full_name, s.student_number, s.academicNo, s.grade, s.section, s.grade_level].join(' ').toLowerCase();
        if (query && !text.includes(query)) return false;
        if (gradeFilter && !text.includes(gradeFilter.toLowerCase())) return false;
        return true;
    });

    let assignedCount = 0;
    let unassignedCount = 0;

    tb.innerHTML = filtered.map((s, idx) => {
        const studentName = s.name || s.full_name || ('طالب ' + (idx + 1));
        const academicNo = s.student_number || s.academicNo || s.id || ('STD-2026-' + String(idx + 101));
        const rawGrade = s.grade_level || s.grade || (idx % 2 === 0 ? 'الثالث الثانوي - علمي 1' : 'التاسع أساسي - أ');

        let stageName = 'المرحلة الثانوية 🏫';
        let gradeName = 'الثالث الثانوي';
        let currentSec = s.section || (idx % 3 === 0 ? 'علمي 1' : (idx % 3 === 1 ? 'علمي 2' : 'أدبي 1'));
        let hall = 'قاعة الخوارزمي - A';
        let supervisor = 'أ. عبد الرحمن باعباد';

        if (rawGrade.includes('ثانوي')) {
            stageName = 'المرحلة الثانوية 🏫';
            gradeName = rawGrade.split('-')[0].trim() || 'الثالث الثانوي';
        } else if (rawGrade.includes('أساسي') || rawGrade.includes('إعدادي') || rawGrade.includes('التاسع')) {
            stageName = 'المرحلة الأساسية 📚';
            gradeName = 'الصف التاسع أساسي';
            currentSec = s.section || (idx % 2 === 0 ? 'شعبة (أ)' : 'شعبة (ب)');
            hall = 'قاعة الرازي - C';
            supervisor = 'أ. خالد العنسي';
        } else {
            stageName = 'مرحلة البراعم 👶';
            gradeName = 'تمهيدي وروضة';
            currentSec = 'براعم المستقبل (KG)';
            hall = 'مبنى الطفولة';
            supervisor = 'أ. منى الحداد';
        }

        let statusBadge = '<span class="badge badge-success"><i class="fa-solid fa-circle-check"></i> موزع ومثبت 🟢</span>';
        if (idx === 3 || idx === 7) {
            unassignedCount++;
            currentSec = 'بانتظار التسكين 🟡';
            statusBadge = '<span class="badge badge-warning"><i class="fa-solid fa-clock"></i> غير موزع 🟡</span>';
        } else {
            assignedCount++;
        }

        // Section select options
        const secOptions = ['علمي 1 (32/35)', 'علمي 2 (28/35)', 'أدبي 1 (30/30)', 'شعبة (أ) (30/30)', 'شعبة (ب) (29/30)', 'براعم 1'].map(opt => {
            const optVal = opt.split(' ')[0];
            const isSel = currentSec.includes(optVal) ? 'selected' : '';
            return `<option value="${optVal}" ${isSel}>${opt}</option>`;
        }).join('');

        return `
            <tr>
                <td style="font-weight:700;color:#94a3b8;text-align:center;">${idx + 1}</td>
                <td><code style="color:#60a5fa;font-weight:800;font-family:monospace;"><i class="fa-solid fa-id-badge"></i> ${academicNo}</code></td>
                <td><strong style="color:#f8fafc;font-size:0.92rem;">👤 ${studentName}</strong></td>
                <td><span style="color:#38bdf8;font-weight:700;">${stageName}</span></td>
                <td style="font-weight:700;color:#f8fafc;">${gradeName}</td>
                <td><span class="badge" style="background:rgba(59,130,246,0.15);color:#60a5fa;border:1px solid rgba(59,130,246,0.3);font-weight:800;">${currentSec}</span></td>
                <td>
                    <select onchange="updateStudentSection('${s.id || idx}', this.value)" style="padding:4px 8px;background:rgba(15,23,42,0.8);border:1px solid rgba(59,130,246,0.3);border-radius:6px;color:#38bdf8;font-size:0.82rem;cursor:pointer;">
                        ${secOptions}
                    </select>
                </td>
                <td style="font-size:0.82rem;color:#cbd5e1;">
                    <i class="fa-solid fa-door-open" style="color:#34d399;"></i> ${hall}<br>
                    <small style="color:#94a3b8;"><i class="fa-solid fa-chalkboard-user"></i> ${supervisor}</small>
                </td>
                <td>${statusBadge}</td>
                <td>
                    <div style="display:flex;gap:4px;justify-content:center;">
                        <button class="btn-action" onclick="if(typeof toast==='function')toast('🔄 تم تأكيد تسكين الطالب: ${studentName}');" title="تأكيد التسكين" style="background:rgba(16,185,129,0.15);color:#34d399;border:1px solid rgba(16,185,129,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-check"></i></button>
                        <button class="btn-action" onclick="goTo('pg-student-tree');if(typeof toast==='function')toast('👁️ استعراض موقع الطالب بالشجرة الهرمية: ${studentName}');" title="عرض بالشجرة" style="background:rgba(59,130,246,0.15);color:#60a5fa;border:1px solid rgba(59,130,246,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-diagram-project"></i></button>
                        <button class="btn-action" onclick="if(typeof toast==='function')toast('🪪 طباعة بطاقة توزيع الطالب: ${studentName}');" title="طباعة البطاقة" style="background:rgba(168,85,247,0.15);color:#c084fc;border:1px solid rgba(168,85,247,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-print"></i></button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    const elTot = document.getElementById('distTotalStudents');
    const elAss = document.getElementById('distAssigned');
    const elUna = document.getElementById('distUnassigned');
    const elSec = document.getElementById('distTotalSections');

    if (elTot) elTot.textContent = String(students.length || 24);
    if (elAss) elAss.textContent = String(assignedCount || Math.round(students.length * 0.9) || 22);
    if (elUna) elUna.textContent = String(unassignedCount || 2);
    if (elSec) elSec.textContent = '18';
}
window.renderSectionDistribution = renderSectionDistribution;




