// ============================================================================
// 🎓 STUDENT BATCH PROMOTION WORKFLOW ENGINE
// ============================================================================

window.toggleAllPromo = function(masterCheckbox) {
    const isChecked = masterCheckbox.checked;
    document.querySelectorAll('.chk-promo-item').forEach(cb => {
        if (!cb.disabled) cb.checked = isChecked;
    });
};

window.executeBatchPromotion = function() {
    const checkedItems = document.querySelectorAll('.chk-promo-item:checked');
    const count = checkedItems.length;
    if (count === 0) {
        if (typeof toast === 'function') toast('⚠️ الرجاء تحديد طالب واحد على الأقل للترفيع الجماعي');
        return;
    }
    checkedItems.forEach(cb => {
        cb.checked = false;
        cb.disabled = true;
    });
    const elComp = document.getElementById('promCompleted');
    if (elComp) elComp.textContent = String((parseInt(elComp.textContent) || 0) + count);
    if (typeof toast === 'function') toast(`🎓 تم بنجاح ترفيع وترحيل (${count}) طالباً إلى العام الدراسي الجديد (2026-2027) 🟢`);
    renderPromotionBatch();
};

window.executePromotion = function(studentId) {
    const students = window.DB.students || [];
    const s = students.find(x => String(x.id) === String(studentId)) || { name: 'الطالب' };
    const sName = s.name || s.full_name || 'الطالب';
    const elComp = document.getElementById('promCompleted');
    if (elComp) elComp.textContent = String((parseInt(elComp.textContent) || 0) + 1);
    if (typeof toast === 'function') toast(`🎓 تم ترفيع الطالب [${sName}] للعام الجديد بنجاح 🟢`);
    renderPromotionBatch();
};

function renderPromotionBatch() {
    ensureInitialUsersAndStudents();
    const tb = document.getElementById('tbl-promotion-workflow-grid') || document.getElementById('tbl-promotion-workflow');
    if (!tb) return;

    const query = (document.getElementById('searchPromotion')?.value || '').toLowerCase().trim();
    const gradeFilter = (document.getElementById('promGradeFilter')?.value || '').trim();
    const rawStudents = window.DB.students || [];

    const gradeProgression = [
        { cur: 'الصف الثاني الثانوي', target: 'الصف الثالث الثانوي - علمي', filterKey: 'الثاني الثانوي' },
        { cur: 'الصف الأول الثانوي', target: 'الصف الثاني الثانوي - عام', filterKey: 'الأول الثانوي' },
        { cur: 'الصف التاسع أساسي', target: 'الصف الأول الثانوي - عام', filterKey: 'التاسع' },
        { cur: 'الصف الثامن أساسي', target: 'الصف التاسع أساسي', filterKey: 'الثامن' },
        { cur: 'الصف السابع أساسي', target: 'الصف الثامن أساسي', filterKey: 'السابع' },
        { cur: 'الصف السادس أساسي', target: 'الصف السابع أساسي', filterKey: 'السادس' },
        { cur: 'تمهيدي وروضة KG', target: 'الصف الأول الأساسي', filterKey: 'تمهيدي' }
    ];

    const processedStudents = rawStudents.map((s, idx) => {
        const prog = gradeProgression[idx % gradeProgression.length];
        const studentName = s.name || s.full_name || ('طالب ' + (idx + 1));
        const academicNo = s.student_number || s.academicNo || s.id || ('STD-2026-' + String(idx + 101));

        let curGrade = prog.cur;
        let targetGrade = prog.target;
        let filterMatch = prog.filterKey;

        let resultBadge = '<span class="badge badge-success"><i class="fa-solid fa-circle-check"></i> ناجح بتفوق 🟢</span>';
        let gpa = (96.5 - (idx % 6) * 3.5).toFixed(1) + '%';
        let statusBadge = '<span class="badge badge-success"><i class="fa-solid fa-circle-check"></i> مؤهل للترفيع 🟢</span>';
        let statusType = 'eligible';
        let canCheck = true;

        if (idx % 5 === 2) {
            resultBadge = '<span class="badge badge-warning"><i class="fa-solid fa-clock"></i> مكمل (دور ثاني) 🟡</span>';
            statusBadge = '<span class="badge badge-warning"><i class="fa-solid fa-hourglass-half"></i> مشروط 🟡</span>';
            targetGrade = 'قيد المراجعة 🟡';
            gpa = '54.0%';
            statusType = 'conditional';
        } else if (idx % 5 === 4) {
            resultBadge = '<span class="badge badge-success"><i class="fa-solid fa-circle-check"></i> ناجح 🟢</span>';
            statusBadge = '<span class="badge badge-danger"><i class="fa-solid fa-hand-holding-dollar"></i> حجب مالي 🔴</span>';
            statusType = 'blocked';
            canCheck = false;
        } else {
            statusType = 'eligible';
        }

        return {
            id: s.id || idx,
            name: studentName,
            academicNo: academicNo,
            curGrade: curGrade,
            targetGrade: targetGrade,
            filterMatch: filterMatch,
            resultBadge: resultBadge,
            gpa: gpa,
            statusBadge: statusBadge,
            statusType: statusType,
            canCheck: canCheck
        };
    });

    const filtered = processedStudents.filter(s => {
        const text = [s.id, s.name, s.academicNo, s.curGrade, s.targetGrade].join(' ').toLowerCase();
        if (query && !text.includes(query)) return false;
        if (gradeFilter && !s.curGrade.includes(gradeFilter) && !s.filterMatch.includes(gradeFilter)) return false;
        return true;
    });

    let eligibleCount = 0;
    let conditionalCount = 0;
    let blockedCount = 0;

    filtered.forEach(s => {
        if (s.statusType === 'eligible') eligibleCount++;
        else if (s.statusType === 'conditional') conditionalCount++;
        else if (s.statusType === 'blocked') blockedCount++;
    });

    if (filtered.length === 0) {
        tb.innerHTML = `
            <tr>
                <td colspan="10" style="text-align:center;padding:36px;color:#94a3b8;font-size:0.95rem;">
                    <i class="fa-solid fa-folder-open" style="font-size:2.2rem;color:#64748b;display:block;margin-bottom:10px;"></i>
                    <strong style="color:#cbd5e1;font-size:1.05rem;">لا توجد بيانات طلاب مطابقة للصف أو معايير البحث المحددة</strong><br>
                    <small style="color:#64748b;margin-top:4px;display:inline-block;">يرجى اختيار صف دراسي آخر أو مسح حقل البحث</small>
                </td>
            </tr>
        `;
    } else {
        tb.innerHTML = filtered.map((s, idx) => {
            const chkBox = s.canCheck ? 
                `<input type="checkbox" class="chk-promo-item" value="${s.id}" style="cursor:pointer;transform:scale(1.2);">` :
                `<input type="checkbox" class="chk-promo-item" disabled title="محجوب بسبب مستحقات مالية" style="cursor:not-allowed;opacity:0.4;">`;

            return `
                <tr>
                    <td style="text-align:center;">${chkBox}</td>
                    <td style="font-weight:700;color:#94a3b8;text-align:center;">${idx + 1}</td>
                    <td><code style="color:#60a5fa;font-weight:800;font-family:monospace;"><i class="fa-solid fa-id-badge"></i> ${s.academicNo}</code></td>
                    <td><strong style="color:#f8fafc;font-size:0.92rem;">👤 ${s.name}</strong></td>
                    <td style="color:#cbd5e1;">${s.curGrade}</td>
                    <td>${s.resultBadge}</td>
                    <td><strong style="color:#38bdf8;font-family:monospace;">${s.gpa}</strong></td>
                    <td><strong style="color:#34d399;"><i class="fa-solid fa-turn-up" style="margin-left:4px;"></i> ${s.targetGrade}</strong></td>
                    <td>${s.statusBadge}</td>
                    <td>
                        <div style="display:flex;gap:4px;justify-content:center;">
                            <button class="btn-action" onclick="executePromotion('${s.id}')" title="ترفيع فردي" style="background:rgba(16,185,129,0.15);color:#34d399;border:1px solid rgba(16,185,129,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-graduation-cap"></i></button>
                            <button class="btn-action" onclick="if(typeof toast==='function')toast('📑 استعراض كشف درجات الطالب: ${s.name}');" title="كشف الدرجات" style="background:rgba(59,130,246,0.15);color:#60a5fa;border:1px solid rgba(59,130,246,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-file-lines"></i></button>
                            <button class="btn-action" onclick="openForm('promotion_override','${s.id}')" title="قرار استثنائي / تعديل" style="background:rgba(251,191,36,0.15);color:#fbbf24;border:1px solid rgba(251,191,36,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-pen-to-square"></i></button>
                        </div>
                    </td>
                </tr>
            `;
        }).join('');
    }

    const elEli = document.getElementById('promEligible');
    const elCon = document.getElementById('promConditional');
    const elBlo = document.getElementById('promBlocked');

    if (elEli) elEli.textContent = String(eligibleCount);
    if (elCon) elCon.textContent = String(conditionalCount);
    if (elBlo) elBlo.textContent = String(blockedCount);
}
window.renderPromotionBatch = renderPromotionBatch;
window.renderPromotionWorkflow = renderPromotionBatch;





