window.notifyParentClassNote = function(noteId, studentName) {
    const notes = window.DB.classNotes || [];
    const n = notes.find(x => String(x.id) === String(noteId));
    if (n) {
        n.notified = true;
    }
    const elNot = document.getElementById('notesNotified');
    if (elNot) elNot.textContent = String((parseInt(elNot.textContent) || 0) + 1);
    if (typeof toast === 'function') toast(`📲 تم إرسال إشعار فوري لولي أمر الطالب [${studentName}] عبر تطبيق ولي الأمر و SMS 🟢`);
    renderClassNotes();
};

