function renderPayrollGrid() {
    const tb = document.getElementById('tbl-payroll-grid') || document.getElementById('tbl-payroll');
    if (!tb) return;

    const employees = [
        { id: 'EMP-101', name: 'أ. عبد الرحمن الصبري', base: 250000, allow: 25000, absDeduct: 0, advDeduct: 0 },
        { id: 'EMP-102', name: 'أ. فاطمة أحمد باحيدرة', base: 230000, allow: 20000, absDeduct: 0, advDeduct: 0 },
        { id: 'EMP-103', name: 'أ. سمير منصور الأهدل', base: 260000, allow: 30000, absDeduct: 0, advDeduct: 30000 },
        { id: 'EMP-104', name: 'أ. محمود عبد القادر الدبعي', base: 200000, allow: 15000, absDeduct: 5000, advDeduct: 0 },
        { id: 'EMP-105', name: 'أ. وفاء عبد الله الحكيمي', base: 280000, allow: 30000, absDeduct: 0, advDeduct: 0 },
        { id: 'EMP-106', name: 'أ. رائد حمود العريقي', base: 300000, allow: 40000, absDeduct: 0, advDeduct: 0 }
    ];

    let totalBase = 0;
    let totalAllow = 0;
    let totalDeduct = 0;
    let totalNet = 0;

    tb.innerHTML = employees.map((p, idx) => {
        const gross = p.base + p.allow;
        const deductions = p.absDeduct + p.advDeduct;
        const net = gross - deductions;

        totalBase += p.base;
        totalAllow += p.allow;
        totalDeduct += deductions;
        totalNet += net;

        return `
            <tr>
                <td style="font-weight:700;color:#94a3b8;text-align:center;">${idx + 1}</td>
                <td><code style="color:#60a5fa;font-family:monospace;">${p.id}</code></td>
                <td><strong style="color:#f8fafc;">👤 ${p.name}</strong></td>
                <td style="color:#cbd5e1;font-family:monospace;">${p.base.toLocaleString()} ر.ي</td>
                <td style="color:#34d399;font-family:monospace;">+${p.allow.toLocaleString()} ر.ي</td>
                <td><strong style="color:#38bdf8;font-family:monospace;">${gross.toLocaleString()} ر.ي</strong></td>
                <td style="color:#f87171;font-family:monospace;">${p.absDeduct > 0 ? '-' + p.absDeduct.toLocaleString() + ' ر.ي' : '-'}</td>
                <td style="color:#fbbf24;font-family:monospace;">${p.advDeduct > 0 ? '-' + p.advDeduct.toLocaleString() + ' ر.ي' : '-'}</td>
                <td><strong style="color:#34d399;font-size:1rem;font-family:monospace;">${net.toLocaleString()} ر.ي</strong></td>
                <td><span class="badge badge-success"><i class="fa-solid fa-circle-check"></i> جاهز للصرف 🟢</span></td>
                <td>
                    <div style="display:flex;gap:4px;justify-content:center;">
                        <button class="btn-action" onclick="if(typeof toast==='function')toast('🧾 طباعة قسيمة الراتب (Payslip) للموظف: ${p.name}');" title="قسيمة الراتب" style="background:rgba(59,130,246,0.15);color:#60a5fa;border:1px solid rgba(59,130,246,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-receipt"></i></button>
                        <button class="btn-action" onclick="openForm('payroll_adjustment','${p.id}')" title="تسوية يدوية" style="background:rgba(251,191,36,0.15);color:#fbbf24;border:1px solid rgba(251,191,36,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-scale-balanced"></i></button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    const elBas = document.getElementById('payrollBase');
    const elAll = document.getElementById('payrollAllowances');
    const elDed = document.getElementById('payrollDeductions');
    const elNet = document.getElementById('payrollNet');

    if (elBas) elBas.textContent = totalBase.toLocaleString() + ' ر.ي';
    if (elAll) elAll.textContent = totalAllow.toLocaleString() + ' ر.ي';
    if (elDed) elDed.textContent = totalDeduct.toLocaleString() + ' ر.ي';
    if (elNet) elNet.textContent = totalNet.toLocaleString() + ' ر.ي';
}
window.renderPayrollGrid = renderPayrollGrid;
window.renderPayroll = renderPayrollGrid;




