// 1. Grading Sheet
function renderGradingSheetGrid() {
    ensureInitialUsersAndStudents();
    const tb = document.getElementById('tbl-grading-grid') || document.getElementById('tbl-grading');
    if (!tb) return;

    const students = window.DB.students || [];
    let completed = 0;

    tb.innerHTML = students.map((s, idx) => {
        const p1 = 18 - (idx % 3);
        const p2 = 9;
        const p3 = 19 - (idx % 4);
        const p4 = 48 - (idx % 6);
        const total = p1 + p2 + p3 + p4;
        let rating = total >= 90 ? 'ممتاز 🟢' : (total >= 75 ? 'جيد جداً 🔵' : 'ناجح 🟢');
        completed++;

        return `
            <tr>
                <td style="font-weight:700;color:#94a3b8;text-align:center;">${idx + 1}</td>
                <td><code style="color:#60a5fa;font-family:monospace;">STD-2026-${idx + 101}</code></td>
                <td><strong style="color:#f8fafc;">👤 ${s.name || s.full_name || 'طالب ' + (idx + 1)}</strong></td>
                <td style="color:#38bdf8;font-family:monospace;font-weight:700;">${p1} / 20</td>
                <td style="color:#34d399;font-family:monospace;font-weight:700;">${p2} / 10</td>
                <td style="color:#fbbf24;font-family:monospace;font-weight:700;">${p3} / 20</td>
                <td style="color:#c084fc;font-family:monospace;font-weight:700;">${p4} / 50</td>
                <td><strong style="color:#34d399;font-size:1.05rem;font-family:monospace;">${total} / 100</strong></td>
                <td><span class="badge ${total >= 90 ? 'badge-success' : 'badge-info'}">${rating}</span></td>
                <td>
                    <button class="btn-action" onclick="openForm('student_grade','${s.id || idx}')" title="تعديل الدرجات" style="background:rgba(251,191,36,0.15);color:#fbbf24;border:1px solid rgba(251,191,36,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-pen-to-square"></i></button>
                </td>
            </tr>
        `;
    }).join('');

    const elTot = document.getElementById('gradeTotal');
    const elCom = document.getElementById('gradeCompleted');
    const elPen = document.getElementById('gradePending');
    const elAvg = document.getElementById('gradeAverage');

    if (elTot) elTot.textContent = String(students.length);
    if (elCom) elCom.textContent = String(completed);
    if (elPen) elPen.textContent = '0';
    if (elAvg) elAvg.textContent = '89.4%';
}
window.renderGradingSheetGrid = renderGradingSheetGrid;
window.renderGrading = renderGradingSheetGrid;

