// 9. Exam Schedule Matrix & List Engine
window.switchExamScheduleView = function(mode) {
    const matElements = document.querySelectorAll('#examScheduleMatrixContainer, [id="examScheduleMatrixContainer"]');
    const listElements = document.querySelectorAll('#examScheduleListContainer, [id="examScheduleListContainer"]');
    const btnMatElements = document.querySelectorAll('#btnViewMatrix, [id="btnViewMatrix"]');
    const btnListElements = document.querySelectorAll('#btnViewList, [id="btnViewList"]');

    if (mode === 'matrix') {
        matElements.forEach(el => el.style.setProperty('display', 'block', 'important'));
        listElements.forEach(el => el.style.setProperty('display', 'none', 'important'));
        
        btnMatElements.forEach(b => {
            b.style.background = 'linear-gradient(135deg,#3b82f6,#2563eb)';
            b.style.color = '#fff';
            b.style.boxShadow = '0 4px 12px rgba(37,99,235,0.4)';
        });
        btnListElements.forEach(b => {
            b.style.background = 'transparent';
            b.style.color = '#94a3b8';
            b.style.boxShadow = 'none';
        });
        if (typeof toast === 'function') toast('📊 تم التبديل إلى: عرض مصفوفة الامتحانات الشاملة (Matrix Grid)');
    } else {
        matElements.forEach(el => el.style.setProperty('display', 'none', 'important'));
        listElements.forEach(el => el.style.setProperty('display', 'block', 'important'));
        
        btnListElements.forEach(b => {
            b.style.background = 'linear-gradient(135deg,#3b82f6,#2563eb)';
            b.style.color = '#fff';
            b.style.boxShadow = '0 4px 12px rgba(37,99,235,0.4)';
        });
        btnMatElements.forEach(b => {
            b.style.background = 'transparent';
            b.style.color = '#94a3b8';
            b.style.boxShadow = 'none';
        });
        if (typeof toast === 'function') toast('📑 تم التبديل إلى: عرض الكشف التفصيلي لجدول الامتحانات');
    }
};

