// 1. School Activities
function renderActivitiesGrid() {
    const tb = document.getElementById('tbl-activities-grid') || document.getElementById('tbl-activities');
    if (!tb) return;

    if (!window.DB.activities || window.DB.activities.length === 0) {
        window.DB.activities = [
            { id: 'ACT-01', code: 'ACT-SPT-01', name: 'دوري كرة القدم السنوي للمرحلة الثانوية', type: 'نشاط رياضي وكروي ⚽', supervisor: 'أ. محمود عبد القادر الدبعي', date: '2026-09-15 ⟵ 2026-10-01', loc: 'الملعب الرياضي الرئيسي', participants: 64, status: 'جاري ونشط 🟢' },
            { id: 'ACT-02', code: 'ACT-CUL-02', name: 'المسابقة المنهجية الثقافية والإذاعية', type: 'نشاط ثقافي وإذاعي 🎭', supervisor: 'أ. فاطمة أحمد باحيدرة', date: '2026-09-20', loc: 'مسرح المدرسة الكبرى', participants: 32, status: 'فعالية قادمة 🟡' },
            { id: 'ACT-03', code: 'ACT-QUR-03', name: 'مسابقة حفظ وتلاوة القرآن الكريم السنوية', type: 'مسابقات قرآنية ودينية 📖', supervisor: 'أ. وفاء الحكيمي', date: '2026-08-28', loc: 'قاعة الأنشطة الدينية', participants: 45, status: 'مكتمل ومنفذ 🔵' },
            { id: 'ACT-04', code: 'ACT-SCI-04', name: 'معرض الابتكارات العلمية والذكاء الاصطناعي', type: 'نشاط علمي ومعملي 🔬', supervisor: 'أ. سمير منصور الأهدل', date: '2026-10-10', loc: 'معامل العلوم المركزية', participants: 28, status: 'فعالية قادمة 🟡' }
        ];
    }

    const query = (document.getElementById('searchActivities')?.value || '').toLowerCase().trim();
    const typeFilter = (document.getElementById('filterActType')?.value || '').trim();
    const items = window.DB.activities || [];

    const filtered = items.filter(a => {
        const text = [a.id, a.code, a.name, a.type, a.supervisor, a.loc].join(' ').toLowerCase();
        if (query && !text.includes(query)) return false;
        if (typeFilter && !a.type.includes(typeFilter)) return false;
        return true;
    });

    let activeCount = 0;
    let upcomingCount = 0;
    let totalPart = 0;

    tb.innerHTML = filtered.map((a, idx) => {
        if (a.status.includes('جاري')) activeCount++;
        else if (a.status.includes('قادمة')) upcomingCount++;
        totalPart += a.participants;

        return `
            <tr>
                <td style="font-weight:700;color:#94a3b8;text-align:center;">${idx + 1}</td>
                <td><code style="color:#60a5fa;font-family:monospace;font-weight:800;">${a.code}</code></td>
                <td><strong style="color:#f8fafc;font-size:0.92rem;">🏆 ${a.name}</strong></td>
                <td><span class="badge badge-info">${a.type}</span></td>
                <td style="color:#cbd5e1;">👨‍🏫 ${a.supervisor}</td>
                <td style="color:#94a3b8;font-family:monospace;font-size:0.85rem;">📅 ${a.date}</td>
                <td style="color:#a78bfa;">📍 ${a.loc}</td>
                <td><strong style="color:#34d399;font-family:monospace;">${a.participants} طالب</strong></td>
                <td><span class="badge ${a.status.includes('جاري') ? 'badge-success' : (a.status.includes('قادمة') ? 'badge-warning' : 'badge-info')}">${a.status}</span></td>
                <td>
                    <div style="display:flex;gap:4px;justify-content:center;">
                        <button class="btn-action" onclick="if(typeof toast==='function')toast('👥 تسجيل مشاركة طلاب في نشاط: ${a.name}');" title="تسجيل طلاب" style="background:rgba(59,130,246,0.15);color:#60a5fa;border:1px solid rgba(59,130,246,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-user-plus"></i></button>
                        <button class="btn-action" onclick="openForm('activity','${a.id}')" title="تعديل النشاط" style="background:rgba(251,191,36,0.15);color:#fbbf24;border:1px solid rgba(251,191,36,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-pen-to-square"></i></button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    const elTot = document.getElementById('actTotal');
    const elAct = document.getElementById('actActive');
    const elPar = document.getElementById('actParticipants');
    const elUpc = document.getElementById('actUpcoming');

    if (elTot) elTot.textContent = String(items.length);
    if (elAct) elAct.textContent = String(activeCount);
    if (elPar) elPar.textContent = String(totalPart) + ' طالب';
    if (elUpc) elUpc.textContent = String(upcomingCount);
}
window.renderActivitiesGrid = renderActivitiesGrid;

