// 4. Student Transport Enrollment
function renderTransportEnrollmentGrid() {
    ensureInitialUsersAndStudents();
    const tb = document.getElementById('tbl-transport-enrollment-grid') || document.getElementById('tbl-transport-enrollment');
    if (!tb) return;

    const students = window.DB.students || [];
    let roundTrip = 0;
    let oneWay = 0;

    tb.innerHTML = students.map((s, idx) => {
        const isRound = idx % 3 !== 0;
        if (isRound) roundTrip++;
        else oneWay++;

        return `
            <tr>
                <td style="font-weight:700;color:#94a3b8;text-align:center;">${idx + 1}</td>
                <td><code style="color:#60a5fa;font-family:monospace;font-weight:800;">TR-SUB-2026-${idx + 101}</code></td>
                <td><strong style="color:#f8fafc;">👤 ${s.name || s.full_name || 'طالب ' + (idx + 1)}</strong></td>
                <td style="color:#cbd5e1;">الثالث الثانوي - علمي 1</td>
                <td><strong style="color:#38bdf8;">خط الروضة (حافلة #1)</strong></td>
                <td style="color:#a78bfa;">📍 جولة الجمنة - محطة 2</td>
                <td><span class="badge ${isRound ? 'badge-success' : 'badge-info'}">${isRound ? 'ذهاب وعودة 🔄' : 'صباحي فقط ☀️'}</span></td>
                <td><strong style="color:#34d399;font-family:monospace;">${isRound ? '180,000 ر.ي' : '100,000 ر.ي'}</strong></td>
                <td><span class="badge badge-success"><i class="fa-solid fa-circle-check"></i> مسدد بالكامل 🟢</span></td>
                <td>
                    <div style="display:flex;gap:4px;justify-content:center;">
                        <button class="btn-action" onclick="if(typeof toast==='function')toast('🪪 طباعة بطاقة ركوب النقل المدرسي للطالب: ${s.name || s.full_name}');" title="بطاقة ركوب" style="background:rgba(59,130,246,0.15);color:#60a5fa;border:1px solid rgba(59,130,246,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-id-badge"></i></button>
                        <button class="btn-action" onclick="openForm('transport_sub','${s.id || idx}')" title="تعديل الاشتراك" style="background:rgba(251,191,36,0.15);color:#fbbf24;border:1px solid rgba(251,191,36,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-pen-to-square"></i></button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    const elTot = document.getElementById('transSubTotal');
    const elRou = document.getElementById('transSubRoundTrip');
    const elOne = document.getElementById('transSubOneWay');
    const elCol = document.getElementById('transSubCollected');

    if (elTot) elTot.textContent = String(students.length);
    if (elRou) elRou.textContent = String(roundTrip);
    if (elOne) elOne.textContent = String(oneWay);
    if (elCol) elCol.textContent = '940,000 ر.ي';
}
window.renderTransportEnrollmentGrid = renderTransportEnrollmentGrid;

// 5. Real-time Bus Tracking
function renderTransportTrackingGrid() {
    const tb = document.getElementById('tbl-transport-tracking-grid') || document.getElementById('tbl-transport-tracking');
    if (!tb) return;

    const liveBuses = [
        { id: 'TRK-01', plate: 'حافلة #1 (لوحة 4410)', line: 'خط الروضة - الحصبة', staff: 'عماد القاضي / أ. مريم', gps: '15.3694° N, 44.1910° E (جولة عمران)', nextStop: 'محطة مدرسة النجاح', leftStudents: 14, speed: '35 كم/س', status: 'في الطريق بالمسار 🟢' },
        { id: 'TRK-02', plate: 'حافلة #2 (لوحة 7721)', line: 'خط حدة - الأصبحي', staff: 'صالح الحيمي / أ. هدى', gps: '15.3142° N, 44.2045° E (شارع حدة)', nextStop: 'محطة بريد حدة (صعود)', leftStudents: 22, speed: '0 كم/س', status: 'صعود وإنزال الطلاب 🟡' },
        { id: 'TRK-03', plate: 'حافلة #3 (لوحة 9934)', line: 'خط الستين - عصر', staff: 'فارس الريمي / أ. سميرة', gps: '15.3501° N, 44.1702° E (فناء المدرسة)', nextStop: 'المدرسة المركزية', leftStudents: 0, speed: '0 كم/س', status: 'اكتملت الرحلة بنجاح 🔵' }
    ];

    let liveCount = 0;
    let stopCount = 0;
    let compCount = 0;

    tb.innerHTML = liveBuses.map((t, idx) => {
        if (t.status.includes('في الطريق')) liveCount++;
        else if (t.status.includes('صعود')) stopCount++;
        else compCount++;

        return `
            <tr>
                <td style="font-weight:700;color:#94a3b8;text-align:center;">${idx + 1}</td>
                <td><code style="color:#60a5fa;font-family:monospace;font-weight:800;"><i class="fa-solid fa-bus"></i> ${t.plate}</code></td>
                <td><strong style="color:#f8fafc;">🛣️ ${t.line}</strong></td>
                <td style="color:#cbd5e1;">👨‍✈️ ${t.staff}</td>
                <td style="color:#38bdf8;font-family:monospace;font-size:0.85rem;"><i class="fa-solid fa-location-crosshairs"></i> ${t.gps}</td>
                <td style="color:#a78bfa;">📍 ${t.nextStop}</td>
                <td><strong style="color:#34d399;font-family:monospace;">${t.leftStudents} طالب</strong></td>
                <td><strong style="color:#fbbf24;font-family:monospace;">${t.speed}</strong></td>
                <td><span class="badge ${t.status.includes('في الطريق') ? 'badge-success' : (t.status.includes('صعود') ? 'badge-warning' : 'badge-info')}">${t.status}</span></td>
                <td>
                    <div style="display:flex;gap:4px;justify-content:center;">
                        <button class="btn-action" onclick="if(typeof toast==='function')toast('🛰️ فتح التتبع المباشر للخريطة القمرية للحافلة: ${t.plate}');" title="خريطة حية" style="background:rgba(59,130,246,0.15);color:#60a5fa;border:1px solid rgba(59,130,246,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-solid fa-satellite"></i></button>
                        <button class="btn-action" onclick="if(typeof toast==='function')toast('📲 إرسال إشعار لحظي لأولياء أمور خط: ${t.line}');" title="إشعار أولياء الأمور" style="background:rgba(16,185,129,0.15);color:#34d399;border:1px solid rgba(16,185,129,0.3);padding:5px 8px;border-radius:6px;cursor:pointer;"><i class="fa-brands fa-whatsapp"></i></button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    const elLiv = document.getElementById('trackLiveBuses');
    const elCom = document.getElementById('trackCompletedTrips');
    const elStp = document.getElementById('trackAtStops');

    if (elLiv) elLiv.textContent = String(liveCount);
    if (elCom) elCom.textContent = String(compCount);
    if (elStp) elStp.textContent = String(stopCount);
}
window.renderTransportTrackingGrid = renderTransportTrackingGrid;
window.renderTransport = renderTransportTrackingGrid;




