function switchParentStudent(studentId) {
    if (!window.parentStudentsData[studentId]) return;
    window.currentParentStudent = studentId;
    const stu = window.parentStudentsData[studentId];

    // Update Header Card
    const elName = document.getElementById('parentStudentName');
    const elId = document.getElementById('parentStudentId');
    const elGrade = document.getElementById('parentStudentGrade');
    const elSel = document.getElementById('parentStudentSwitcher');

    if (elName) elName.textContent = stu.name;
    if (elId) elId.textContent = stu.id;
    if (elGrade) elGrade.textContent = stu.grade;
    if (elSel && elSel.value !== studentId) elSel.value = studentId;

    // Update KPIs
    const elKpiG = document.getElementById('parentKpiGrade');
    const elKpiA = document.getElementById('parentKpiAtt');
    const elKpiF = document.getElementById('parentKpiFees');
    const elKpiH = document.getElementById('parentKpiHw');

    if (elKpiG) elKpiG.textContent = stu.kpiGrade;
    if (elKpiA) elKpiA.textContent = stu.kpiAtt;
    if (elKpiF) elKpiF.textContent = stu.kpiFees;
    if (elKpiH) elKpiH.textContent = stu.kpiHw;

    if (typeof toast === 'function') {
        toast(`🔄 تم تبديل ملف الطالب إلى: ${stu.name} (${stu.grade}) 🟢`);
    }
}
