function renderAlertsGrid() {
    const tb = document.getElementById('tbl-alerts-grid');
    if (!tb) return;

    const sVal = (document.getElementById('searchAlerts')?.value || '').trim().toLowerCase();
    const fChannel = (document.getElementById('filterAlertChannel')?.value || '').trim().toLowerCase();
    const fStatus = (document.getElementById('filterAlertStatus')?.value || '').trim();

    let rules = window.DB.alertsRules || [];

    if (sVal) {
        rules = rules.filter(r => 
            r.code.toLowerCase().includes(sVal) || 
            r.title.toLowerCase().includes(sVal) || 
            r.preview.toLowerCase().includes(sVal) || 
            r.audience.toLowerCase().includes(sVal) || 
            r.channel.toLowerCase().includes(sVal)
        );
    }

    if (fChannel) {
        rules = rules.filter(r => r.channel.toLowerCase().includes(fChannel) || r.channel.includes('All'));
    }

    if (fStatus) {
        rules = rules.filter(r => r.status.includes(fStatus));
    }

    // Update KPI counters
    const activeCount = (window.DB.alertsRules || []).filter(r => r.status.includes('نشط')).length;
    const statActive = document.getElementById('statAlertActiveRules');
    if (statActive) statActive.textContent = `${activeCount} قواعد آلية 🟢`;

    const totalSent = (window.DB.alertsRules || []).reduce((acc, r) => acc + (r.recipientsCount || 0), 0);
    const statSent = document.getElementById('statAlertTotalSent');
    if (statSent) statSent.textContent = `${totalSent.toLocaleString()} إشعار`;

    if (rules.length === 0) {
        tb.innerHTML = `
            <tr>
                <td colspan="8" style="text-align:center;padding:40px 20px;">
                    <div style="color:#94a3b8;font-size:1.1rem;margin-bottom:8px;"><i class="fa-solid fa-bell-slash" style="font-size:2rem;color:#64748b;margin-bottom:8px;display:block;"></i> لا توجد قواعد تنبيه مطابقة لمعايير البحث</div>
                    <button class="btn-add" onclick="openNewAlertModal()" style="display:inline-flex;margin:0 auto;background:linear-gradient(135deg,#0284c7,#0369a1);"><i class="fa-solid fa-plus"></i> إضافة قاعدة تنبيه جديدة</button>
                </td>
            </tr>
        `;
        return;
    }

    tb.innerHTML = rules.map((r, idx) => {
        const isAct = r.status.includes('نشط');
        const statusBadge = isAct 
            ? '<span class="badge badge-success"><i class="fa-solid fa-circle-check"></i> نشط ومفعل 🟢</span>'
            : '<span class="badge badge-warning"><i class="fa-solid fa-circle-pause"></i> معطل مؤقتاً ⏸️</span>';

        return `
            <tr>
                <td><code style="color:#38bdf8;font-weight:800;font-family:monospace;font-size:0.9rem;">${r.code}</code></td>
                <td>
                    <div style="font-weight:800;color:#f8fafc;font-size:0.92rem;margin-bottom:2px;">${r.title}</div>
                    <div style="font-size:0.8rem;color:#94a3b8;line-height:1.4;">${r.preview}</div>
                </td>
                <td style="font-weight:600;color:#cbd5e1;font-size:0.85rem;">${r.audience}</td>
                <td style="font-size:0.83rem;color:#94a3b8;"><i class="fa-solid fa-bolt" style="color:#fbbf24;margin-left:4px;"></i> ${r.trigger}</td>
                <td><span class="badge badge-info">${r.channel}</span></td>
                <td>${statusBadge}</td>
                <td style="font-size:0.83rem;color:#cbd5e1;">
                    ${r.lastSent}
                    <div style="color:#94a3b8;font-size:0.75rem;">(${r.recipientsCount || 0} مستلم)</div>
                </td>
                <td>
                    <div style="display:flex;gap:6px;justify-content:center;flex-wrap:wrap;">
                        <button class="btn-action" onclick="sendAlertNow('${r.code}')" title="إرسال التنبيه الآن" style="background:rgba(2,132,199,0.2);color:#38bdf8;border:1px solid rgba(2,132,199,0.4);padding:6px 10px;border-radius:6px;cursor:pointer;font-weight:700;font-size:0.8rem;">
                            <i class="fa-solid fa-paper-plane"></i> إرسال الآن
                        </button>
                        <button class="btn-action" onclick="toggleAlertRuleStatus('${r.code}')" title="${isAct ? 'تعطيل مؤقت' : 'تفعيل القاعدة'}" style="background:rgba(245,158,11,0.15);color:#fbbf24;border:1px solid rgba(245,158,11,0.3);padding:6px 8px;border-radius:6px;cursor:pointer;">
                            <i class="fa-solid ${isAct ? 'fa-pause' : 'fa-play'}"></i>
                        </button>
                        <button class="btn-action" onclick="deleteAlertRule('${r.code}')" title="حذف القاعدة" style="background:rgba(239,68,68,0.15);color:#f87171;border:1px solid rgba(239,68,68,0.3);padding:6px 8px;border-radius:6px;cursor:pointer;">
                            <i class="fa-solid fa-trash"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}
