function insertAlertTag(tag) {
    const tArea = document.getElementById('newAlertTemplate');
    if (!tArea) return;
    const start = tArea.selectionStart || tArea.value.length;
    const end = tArea.selectionEnd || tArea.value.length;
    const text = tArea.value;
    tArea.value = text.substring(0, start) + ' ' + tag + ' ' + text.substring(end);
    tArea.focus();
}
window.insertAlertTag = insertAlertTag;

function saveNewAlertRule(e) {
    if (e && typeof e.preventDefault === 'function') e.preventDefault();

    const code = document.getElementById('newAlertCode')?.value || 'ALT-2026-006';
    const title = (document.getElementById('newAlertTitle')?.value || '').trim();
    const audience = document.getElementById('newAlertAudience')?.value || '👥 أولياء الأمور';
    const trigger = document.getElementById('newAlertTrigger')?.value || '⚡ عند تسجيل غياب صباحي';
    const template = (document.getElementById('newAlertTemplate')?.value || '').trim();
    const status = document.getElementById('newAlertStatus')?.value || 'نشط ومفعل 🟢';

    if (!title || !template) {
        if (typeof toast === 'function') toast('⚠️ يرجى كتابة عنوان التنبيه ونص الرسالة');
        return;
    }

    // Build channels list
    const chans = [];
    if (document.getElementById('chkChanWhatsapp')?.checked) chans.push('WhatsApp');
    if (document.getElementById('chkChanSms')?.checked) chans.push('SMS');
    if (document.getElementById('chkChanPush')?.checked) chans.push('Push');
    if (document.getElementById('chkChanEmail')?.checked) chans.push('Email');
    const channelStr = chans.length > 0 ? chans.join(' + ') + ' 📱' : 'All Channels';

    if (!window.DB.alertsRules) window.DB.alertsRules = [];
    
    window.DB.alertsRules.unshift({
        code: code,
        title: title,
        preview: template,
        audience: audience,
        trigger: trigger,
        channel: channelStr,
        status: status,
        lastSent: '🕒 لم يتم الإرسال بعد (جديد)',
        recipientsCount: 0
    });

    closeNewAlertModal();
    renderAlertsGrid();

    if (typeof toast === 'function') toast(`🟢 تم إضافة قاعدة التنبيه الذكية (${code}) بنجاح!`);
    if (typeof addAudit === 'function') addAudit('إنشاء قاعدة تنبيه', `تم إضافة قاعدة تنبيه جديدة: ${title} (${code})`);
}
window.saveNewAlertRule = saveNewAlertRule;

function toggleAlertRuleStatus(code) {
    const r = (window.DB.alertsRules || []).find(x => x.code === code);
    if (!r) return;

    if (r.status.includes('نشط')) {
        r.status = 'معطل مؤقتاً ⏸️';
        if (typeof toast === 'function') toast(`⏸️ تم إيقاف قاعدة التنبيه (${code}) مؤقتاً`);
    } else {
        r.status = 'نشط ومفعل 🟢';
        if (typeof toast === 'function') toast(`🟢 تم تفعيل وتشغيل قاعدة التنبيه (${code})`);
    }

    renderAlertsGrid();
}
window.toggleAlertRuleStatus = toggleAlertRuleStatus;

function deleteAlertRule(code) {
    if (!confirm(`هل أنت متأكد من رغبتك في حذف قاعدة التنبيه (${code})؟`)) return;

    window.DB.alertsRules = (window.DB.alertsRules || []).filter(x => x.code !== code);
    renderAlertsGrid();

    if (typeof toast === 'function') toast(`🗑️ تم حذف قاعدة التنبيه (${code}) بنجاح`);
}
window.deleteAlertRule = deleteAlertRule;

function sendAlertNow(code) {
    const r = (window.DB.alertsRules || []).find(x => x.code === code);
    const title = r ? r.title : code;

    if (typeof toast === 'function') {
        toast(`🚀 تم إطلاق وإرسال التنبيه (${title}) بنجاح لكافة المستهدفين!`);
    }

    if (r) {
        r.recipientsCount = (r.recipientsCount || 0) + 45;
        r.lastSent = '🕒 الآن (بث فوري مباشر)';
        renderAlertsGrid();
    }
}
window.sendAlertNow = sendAlertNow;

function sendAllScheduledAlerts() {
    if (typeof toast === 'function') {
        toast('🔔 تم تشغيل الفحص الآلي وإرسال كافة التنبيهات المجدولة بنجاح!');
    }
}
window.sendAllScheduledAlerts = sendAllScheduledAlerts;




