function renderArchiveGrid() {
    const tb = document.getElementById('tbl-archive-grid');
    if (!tb) return;

    const sVal = (document.getElementById('searchArchive')?.value || '').trim().toLowerCase();
    const fCat = (document.getElementById('filterArchiveCategory')?.value || '').trim();
    const fSec = (document.getElementById('filterArchiveSecurity')?.value || '').trim();

    let docs = window.DB.archiveDocs || [];

    if (sVal) {
        docs = docs.filter(d => 
            d.code.toLowerCase().includes(sVal) || 
            d.title.toLowerCase().includes(sVal) || 
            d.hashtags.toLowerCase().includes(sVal) || 
            d.refNo.toLowerCase().includes(sVal) || 
            d.category.toLowerCase().includes(sVal) || 
            d.archivist.toLowerCase().includes(sVal)
        );
    }

    if (fCat) {
        docs = docs.filter(d => d.category.includes(fCat));
    }

    if (fSec) {
        docs = docs.filter(d => d.security.includes(fSec));
    }

    // Update KPIs
    const totalCount = (window.DB.archiveDocs || []).length;
    const statTotal = document.getElementById('statArchiveTotalDocs');
    if (statTotal) statTotal.textContent = `${totalCount} وثائق رسمية`;

    const topSecretCount = (window.DB.archiveDocs || []).filter(d => d.security.includes('سري للغاية') || d.security.includes('سري جداً')).length;
    const statTopSecret = document.getElementById('statArchiveTopSecret');
    if (statTopSecret) statTopSecret.textContent = `${topSecretCount} وثائق سيادية 🔴`;

    if (docs.length === 0) {
        tb.innerHTML = `
            <tr>
                <td colspan="9" style="text-align:center;padding:40px 20px;">
                    <div style="color:#94a3b8;font-size:1.1rem;margin-bottom:8px;"><i class="fa-solid fa-folder-open" style="font-size:2rem;color:#64748b;margin-bottom:8px;display:block;"></i> لا توجد وثائق مطابقة لمعايير البحث في الأرشيف</div>
                    <button class="btn-add" onclick="openNewArchiveModal()" style="display:inline-flex;margin:0 auto;background:linear-gradient(135deg,#0284c7,#0369a1);"><i class="fa-solid fa-plus"></i> أرشفة وثيقة جديدة</button>
                </td>
            </tr>
        `;
        return;
    }

    tb.innerHTML = docs.map((d, idx) => {
        let secBadge = '<span class="badge badge-info">' + d.security + '</span>';
        if (d.security.includes('سري للغاية') || d.security.includes('سري جداً') || d.security.includes('سري')) {
            secBadge = '<span class="badge badge-danger">' + d.security + '</span>';
        } else if (d.security.includes('خاص')) {
            secBadge = '<span class="badge badge-warning">' + d.security + '</span>';
        } else if (d.security.includes('عادي')) {
            secBadge = '<span class="badge badge-success">' + d.security + '</span>';
        }

        return `
            <tr>
                <td><code style="color:#38bdf8;font-weight:800;font-family:monospace;font-size:0.9rem;">${d.code}</code></td>
                <td>
                    <div style="font-weight:800;color:#f8fafc;font-size:0.92rem;margin-bottom:2px;">${d.title}</div>
                    <div style="font-size:0.78rem;color:#94a3b8;font-family:inherit;">${d.hashtags}</div>
                </td>
                <td><span class="badge badge-info" style="font-size:0.75rem;">${d.category}</span></td>
                <td><code style="color:#cbd5e1;font-family:monospace;">${d.refNo}</code></td>
                <td><span style="color:#cbd5e1;font-size:0.85rem;">${d.format}</span></td>
                <td>${secBadge}</td>
                <td style="font-size:0.85rem;color:#cbd5e1;white-space:nowrap;">📅 ${d.archivedDate}</td>
                <td style="font-size:0.85rem;color:#f8fafc;white-space:nowrap;">👤 ${d.archivist}</td>
                <td>
                    <div style="display:flex;gap:5px;justify-content:center;">
                        <button class="btn-action" onclick="downloadArchiveDoc('${d.code}')" title="تنزيل المستند الأصلي" style="background:rgba(16,185,129,0.18);color:#34d399;border:1px solid rgba(16,185,129,0.35);padding:5px 8px;border-radius:6px;cursor:pointer;">
                            <i class="fa-solid fa-download"></i>
                        </button>
                        <button class="btn-action" onclick="viewArchiveDoc('${d.code}')" title="معاينة المستند المشفر" style="background:rgba(56,189,248,0.18);color:#38bdf8;border:1px solid rgba(56,189,248,0.35);padding:5px 8px;border-radius:6px;cursor:pointer;">
                            <i class="fa-solid fa-eye"></i>
                        </button>
                        <button class="btn-action" onclick="deleteArchiveDoc('${d.code}')" title="حذف المستند من الأرشيف" style="background:rgba(239,68,68,0.18);color:#f87171;border:1px solid rgba(239,68,68,0.35);padding:5px 8px;border-radius:6px;cursor:pointer;">
                            <i class="fa-solid fa-trash"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}
window.renderArchiveGrid = renderArchiveGrid;

function openNewArchiveModal() {
    const modal = document.getElementById('modalNewArchiveDoc');
    if (!modal) return;

    const count = (window.DB.archiveDocs || []).length + 1;
    const nextCode = 'DOC-2026-' + String(count).padStart(3, '0');
    
    const elCode = document.getElementById('newDocCode');
    if (elCode) elCode.value = nextCode;

    const curUser = (window.me && window.me.name) ? window.me.name : 'أ. خالد العنسي (المدير العام)';
    const elArchivist = document.getElementById('newDocArchivist');
    if (elArchivist) elArchivist.value = '👤 ' + curUser;

    const form = document.getElementById('formNewArchiveDoc');
    if (form) {
        document.getElementById('newDocTitle').value = '';
        document.getElementById('newDocRef').value = 'REF-GEN-2026-' + Math.floor(1000 + Math.random() * 9000);
        document.getElementById('newDocHashtags').value = '';
        const fnBox = document.getElementById('selectedFileName');
        if (fnBox) fnBox.textContent = '';
    }

    modal.style.display = 'flex';
}
window.openNewArchiveModal = openNewArchiveModal;

function closeNewArchiveModal() {
    const modal = document.getElementById('modalNewArchiveDoc');
    if (modal) modal.style.display = 'none';
}
window.closeNewArchiveModal = closeNewArchiveModal;

function saveNewArchiveDoc(e) {
    if (e && typeof e.preventDefault === 'function') e.preventDefault();

    const code = document.getElementById('newDocCode')?.value || 'DOC-2026-006';
    const title = (document.getElementById('newDocTitle')?.value || '').trim();
    const refNo = (document.getElementById('newDocRef')?.value || 'REF-GEN-2026').trim();
    const category = document.getElementById('newDocCategory')?.value || 'الوثائق السيادية والترخيص';
    const security = document.getElementById('newDocSecurity')?.value || 'سري للغاية 🔴';
    const format = document.getElementById('newDocFormat')?.value || 'PDF (ممسوح ضوئياً 📄)';
    const hashtags = (document.getElementById('newDocHashtags')?.value || '#وثيقة #أرشيف_2026').trim();
    const archivist = (window.me && window.me.name) ? window.me.name : 'أ. خالد العنسي (المدير العام)';

    if (!title) {
        if (typeof toast === 'function') toast('⚠️ يرجى كتابة عنوان الوثيقة الرسمي');
        return;
    }

    const todayStr = new Date().toISOString().split('T')[0];

    if (!window.DB.archiveDocs) window.DB.archiveDocs = [];

    window.DB.archiveDocs.unshift({
        code: code,
        title: title,
        hashtags: hashtags,
        category: category,
        refNo: refNo,
        format: format,
        security: security,
        archivedDate: todayStr,
        archivist: archivist
    });

    closeNewArchiveModal();
    renderArchiveGrid();

    if (typeof toast === 'function') toast(`🟢 تم أرشفة وتشفير الوثيقة (${code}) بنجاح!`);
    if (typeof addAudit === 'function') addAudit('أرشفة وثيقة', `تم إيداع وثيقة جديدة بالأرشيف: ${title} (${code})`);
}
window.saveNewArchiveDoc = saveNewArchiveDoc;

function downloadArchiveDoc(code) {
    const d = (window.DB.archiveDocs || []).find(x => x.code === code);
    const title = d ? d.title : code;
    if (typeof toast === 'function') toast(`⬇️ جاري تنزيل الملف المصدق: ${title}`);
}
window.downloadArchiveDoc = downloadArchiveDoc;

function viewArchiveDoc(code) {
    const d = (window.DB.archiveDocs || []).find(x => x.code === code);
    const title = d ? d.title : code;
    if (typeof toast === 'function') toast(`👁️ استعراض الوثيقة المشفرة بـ AES-256: ${title}`);
}
window.viewArchiveDoc = viewArchiveDoc;

function deleteArchiveDoc(code) {
    if (!confirm(`هل أنت متأكد من رغبتك في حذف الوثيقة (${code}) من الأرشيف نهائياً؟`)) return;

    window.DB.archiveDocs = (window.DB.archiveDocs || []).filter(x => x.code !== code);
    renderArchiveGrid();

    if (typeof toast === 'function') toast(`🗑️ تم حذف الوثيقة (${code}) من الأرشيف`);
}
window.deleteArchiveDoc = deleteArchiveDoc;




