function renderPostingGrid() {
    const tb = document.getElementById('tbl-posting-grid');
    if (!tb) return;

    const sVal = (document.getElementById('searchPosting')?.value || '').trim().toLowerCase();
    const fType = (document.getElementById('filterPostingType')?.value || '').trim();
    const fStatus = (document.getElementById('filterPostingStatus')?.value || '').trim();

    let batches = window.DB.postingBatches || [];

    if (sVal) {
        batches = batches.filter(b => 
            b.code.toLowerCase().includes(sVal) || 
            b.type.toLowerCase().includes(sVal) || 
            b.desc.toLowerCase().includes(sVal) || 
            b.accountant.toLowerCase().includes(sVal)
        );
    }

    if (fType) {
        batches = batches.filter(b => b.type.includes(fType));
    }

    if (fStatus) {
        batches = batches.filter(b => b.status.includes(fStatus));
    }

    // Update KPI counters dynamically
    const pendingBatches = (window.DB.postingBatches || []).filter(b => b.status.includes('بانتظار'));
    const pendingCount = pendingBatches.length;
    const pendingAmount = pendingBatches.reduce((acc, b) => acc + (b.amount || 0), 0);

    const elCount = document.getElementById('unpostedBatchesCount');
    if (elCount) elCount.textContent = `${pendingCount} دفعات`;

    const elAmount = document.getElementById('unpostedBatchesAmount');
    if (elAmount) elAmount.textContent = `${pendingAmount.toLocaleString()} YER`;

    const lastPosted = (window.DB.postingBatches || []).find(b => b.status.includes('تم الترحيل'));
    const elLast = document.getElementById('lastSuccessfulBatch');
    if (elLast && lastPosted) elLast.textContent = lastPosted.code;

    if (batches.length === 0) {
        tb.innerHTML = `
            <tr>
                <td colspan="8" style="text-align:center;padding:40px 20px;">
                    <div style="color:#94a3b8;font-size:1.1rem;margin-bottom:8px;"><i class="fa-solid fa-receipt" style="font-size:2rem;color:#64748b;margin-bottom:8px;display:block;"></i> لا توجد دفعات ترحيل مطابقة للبحث</div>
                    <button class="btn-add" onclick="openNewPostingBatchModal()" style="display:inline-flex;margin:0 auto;background:linear-gradient(135deg,#0284c7,#0369a1);"><i class="fa-solid fa-plus"></i> إنشاء دفعة ترحيل جديدة</button>
                </td>
            </tr>
        `;
        return;
    }

    tb.innerHTML = batches.map((b, idx) => {
        const isPending = b.status.includes('بانتظار');
        const statusBadge = isPending 
            ? '<span class="badge badge-warning"><i class="fa-solid fa-clock"></i> بانتظار الترحيل ⏳</span>'
            : '<span class="badge badge-success"><i class="fa-solid fa-circle-check"></i> تم الترحيل للأستاذ العام 🟢</span>';

        return `
            <tr>
                <td><code style="color:#38bdf8;font-weight:800;font-family:monospace;font-size:0.9rem;">${b.code}</code></td>
                <td style="color:#cbd5e1;white-space:nowrap;">📅 ${b.date}</td>
                <td>
                    <div style="font-weight:800;color:#f8fafc;font-size:0.92rem;margin-bottom:2px;">${b.type}</div>
                    <div style="font-size:0.8rem;color:#94a3b8;line-height:1.4;">${b.desc}</div>
                </td>
                <td><strong style="color:#34d399;font-weight:800;font-family:monospace;font-size:0.95rem;">${(b.amount || 0).toLocaleString()} YER</strong></td>
                <td><span class="badge badge-info">${b.recordsCount} ${b.recordsUnit || 'سجل'}</span></td>
                <td>${statusBadge}</td>
                <td style="font-size:0.85rem;color:#f8fafc;white-space:nowrap;">👤 ${b.accountant}</td>
                <td>
                    <div style="display:flex;gap:6px;justify-content:center;flex-wrap:wrap;">
                        ${isPending ? `
                            <button class="btn-action" onclick="postBatchNow('${b.code}')" title="ترحيل فوري للأستاذ العام" style="background:rgba(2,132,199,0.2);color:#38bdf8;border:1px solid rgba(2,132,199,0.4);padding:6px 10px;border-radius:6px;cursor:pointer;font-weight:700;font-size:0.8rem;">
                                <i class="fa-solid fa-bolt"></i> ترحيل فوري ⚡
                            </button>
                        ` : ''}
                        <button class="btn-action" onclick="viewBatchDetails('${b.code}')" title="معاينة تفاصيل السندات" style="background:rgba(100,116,139,0.2);color:#cbd5e1;border:1px solid rgba(100,116,139,0.3);padding:6px 10px;border-radius:6px;cursor:pointer;font-weight:700;font-size:0.8rem;">
                            <i class="fa-solid fa-eye"></i> معاينة تفاصيل السندات 👁️
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}
