function saveNewPostingBatch(e) {
    if (e && typeof e.preventDefault === 'function') e.preventDefault();

    const code = document.getElementById('newBatchCode')?.value || 'BATCH-2026-083';
    const type = document.getElementById('newBatchType')?.value || 'سندات القبض المالية';
    const desc = (document.getElementById('newBatchDescription')?.value || '').trim();
    const amount = parseFloat(document.getElementById('newBatchAmount')?.value || '0');
    const recordsCount = parseInt(document.getElementById('newBatchRecordsCount')?.value || '1');
    const accountant = (window.me && window.me.name) ? window.me.name : 'أ. سارة المحاسبة';

    if (!desc) {
        if (typeof toast === 'function') toast('⚠️ يرجى كتابة البيان والوصف المحاسبي للدفعة');
        return;
    }

    const todayStr = new Date().toISOString().split('T')[0];

    if (!window.DB.postingBatches) window.DB.postingBatches = [];

    window.DB.postingBatches.unshift({
        code: code,
        date: todayStr,
        type: type,
        desc: desc,
        amount: amount,
        recordsCount: recordsCount,
        recordsUnit: 'سند مالي',
        status: 'بانتظار الترحيل ⏳',
        accountant: accountant
    });

    closeNewPostingBatchModal();
    renderPostingGrid();

    if (typeof toast === 'function') toast(`🟢 تم إنشاء واعتماد الدفعة (${code}) بنجاح بحالة: بانتظار الترحيل ⏳`);
    if (typeof addAudit === 'function') addAudit('إنشاء دفعة ترحيل', `تم تجميع دفعة ترحيل جديدة: ${type} بمبلغ ${amount.toLocaleString()} YER (${code})`);
}
window.saveNewPostingBatch = saveNewPostingBatch;

function postBatchNow(code) {
    const b = (window.DB.postingBatches || []).find(x => x.code === code);
    if (!b) return;

    b.status = 'تم الترحيل للأستاذ العام 🟢';
    renderPostingGrid();

    if (typeof toast === 'function') {
        toast(`⚡ تم ترحيل الدفعة (${code}) بنجاح إلى دفتر الأستاذ العام وتحديث أرصدة الحسابات!`);
    }
    if (typeof addAudit === 'function') {
        addAudit('ترحيل مالي', `تم ترحيل الدفعة ${code} بقيمة ${b.amount.toLocaleString()} YER للأستاذ العام`);
    }
}
window.postBatchNow = postBatchNow;

function postAllPendingBatches() {
    const pendings = (window.DB.postingBatches || []).filter(b => b.status.includes('بانتظار'));
    if (pendings.length === 0) {
        if (typeof toast === 'function') toast('ℹ️ لا توجد دفعات معلقة حالياً، كافة الحسابات مرحلة بالكامل 🟢');
        return;
    }

    pendings.forEach(b => {
        b.status = 'تم الترحيل للأستاذ العام 🟢';
    });

    renderPostingGrid();

    if (typeof toast === 'function') {
        toast(`⚡ تم ترحيل كافة الدفعات المعلقة (${pendings.length} دفعات) دفعة واحدة إلى دفتر الأستاذ العام!`);
    }
    if (typeof addAudit === 'function') {
        addAudit('ترحيل شامل', `تم تشغيل الترحيل الشامل لكافة المعلقات`);
    }
}
window.postAllPendingBatches = postAllPendingBatches;

