// 🏫 Auto-Populate All 30 Registered Schools into Login Dropdown
function populateLoginSchoolSelect() {
    const sel = document.getElementById('schoolId');
    if (!sel) return;
    const schools = (window.DB && window.DB.schoolsList && window.DB.schoolsList.length > 0) ? window.DB.schoolsList : null;
    if (!schools) return;

    const currentVal = sel.value;
    sel.innerHTML = schools.map((s, idx) => {
        const val = s.id || `SCH-${String(idx + 1).padStart(2, '0')}`;
        return `<option value="${val}">🏫 ${s.name} (${s.city || (s.governorate + ' — ' + s.district)})</option>`;
    }).join('');
    if (currentVal && Array.from(sel.options).some(o => o.value === currentVal)) {
        sel.value = currentVal;
    }
}
window.populateLoginSchoolSelect = populateLoginSchoolSelect;
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', populateLoginSchoolSelect);
} else {
    populateLoginSchoolSelect();
}


// ============================================================================
// 🏫 DEDICATED SCHOOL PORTAL: PROFILE & USERS ISOLATION ENGINE
// ============================================================================

function getActiveSchoolEntity() {
    if (!window.DB) window.DB = {};
    const schools = (window.DB.schoolsList && Array.isArray(window.DB.schoolsList)) ? window.DB.schoolsList : [];
    if (schools.length === 0) return null;

    let targetCode = '';
    let targetNum = null;

    if (window.me) {
        if (window.me.schoolCode && window.me.schoolCode !== 'ALL') {
            targetCode = String(window.me.schoolCode).trim();
            targetNum = parseInt(targetCode.replace(/\D/g, ''));
        } else if (window.me.schoolId && window.me.schoolId !== 'ALL') {
            targetNum = parseInt(String(window.me.schoolId).replace(/\D/g, ''));
            targetCode = targetNum ? `SCH-${String(targetNum).padStart(2, '0')}` : '';
        }
    }
    
    if (!targetCode && window.currentSchoolCode && window.currentSchoolCode !== 'ALL') {
        targetCode = String(window.currentSchoolCode).trim();
        targetNum = parseInt(targetCode.replace(/\D/g, ''));
    }
    if (!targetCode && window.currentSchoolId && window.currentSchoolId !== 'ALL') {
        targetNum = parseInt(String(window.currentSchoolId).replace(/\D/g, ''));
        targetCode = targetNum ? `SCH-${String(targetNum).padStart(2, '0')}` : '';
    }

    if (!targetCode) {
        targetCode = 'SCH-01';
        targetNum = 1;
    }

    const padStr = targetNum ? String(targetNum).padStart(2, '0') : '';

    const school = schools.find(s => 
        (s.id && s.id.toUpperCase() === targetCode.toUpperCase()) ||
        (s.code && s.code.toUpperCase() === targetCode.toUpperCase()) ||
        (padStr && s.id && s.id.endsWith(padStr))
    ) || schools[0];

    return school;
}
window.getActiveSchoolEntity = getActiveSchoolEntity;

function renderSchoolProfile() {
    const school = getActiveSchoolEntity();
    if (!school) return;

    const num = parseInt(String(school.id).replace(/\D/g, '')) || 1;
    const numStr = String(num).padStart(2, '0');
    const defaultLogo = `/assets/images/schools/sch_${numStr}_logo.svg`;
    const defaultCampus = `/assets/images/schools/sch_${numStr}_campus.svg`;

    // 1. Header elements
    const logoEl = document.getElementById('spHeaderLogo');
    if (logoEl) logoEl.src = school.logo || defaultLogo;

    const campusEl = document.getElementById('spHeaderCampus');
    if (campusEl) campusEl.src = school.campusPhoto || defaultCampus;

    const nameEl = document.getElementById('spHeaderName');
    if (nameEl) nameEl.textContent = school.name;

    const nameEnEl = document.getElementById('spHeaderNameEn');
    if (nameEnEl) nameEnEl.textContent = school.nameEn || '';

    const locEl = document.getElementById('spHeaderLocation');
    if (locEl) locEl.innerHTML = `<i class="fa-solid fa-location-dot" style="color:#ef4444;margin-left:4px;"></i> ${school.city || (school.governorate + ' — ' + school.district)}`;

    const codeEl = document.getElementById('spHeaderCode');
    if (codeEl) codeEl.innerHTML = `<i class="fa-solid fa-hashtag" style="margin-left:2px;"></i> كود المنشأة: ${school.code || school.id}`;

    const licEl = document.getElementById('spHeaderLicense');
    if (licEl) licEl.innerHTML = `<i class="fa-solid fa-file-contract" style="margin-left:4px;"></i> ترخيص وزارة التربية: ${school.license || 'LIC-2026-9941'}`;

    // 2. KPIs
    const kpiStd = document.getElementById('spKpiStudents');
    if (kpiStd) kpiStd.textContent = `${school.studentsCount || 100} طالب`;

    const kpiCap = document.getElementById('spKpiCapacity');
    if (kpiCap) kpiCap.textContent = 'الطلاب المقيدون حالياً بالمنشأة 🧑‍🎓';

    const kpiStf = document.getElementById('spKpiStaff');
    if (kpiStf) kpiStf.textContent = `${school.teachersCount || 12} موظف ومعلم`;

    const kpiTrn = document.getElementById('spKpiTransport');
    if (kpiTrn) kpiTrn.textContent = `${school.busesCount || 3} حافلات (${school.routesCount || 3} خطوط)`;

    const kpiEst = document.getElementById('spKpiEst');
    if (kpiEst) kpiEst.textContent = `${school.est || '1998'} م`;

    // 3. Form fields
    const setVal = (id, val) => { const el = document.getElementById(id); if (el) el.value = (val !== undefined && val !== null) ? val : ''; };
    setVal('spSchoolId', school.id);
    setVal('spName', school.name);
    setVal('spNameEn', school.nameEn);
    setVal('spMotto', school.motto || 'نحو جيل مبدع ومتميز');
    setVal('spEst', school.est || '1998');
    setVal('spGovernorate', school.governorate);
    setVal('spDistrict', school.district);
    setVal('spCity', school.city);
    setVal('spAddress', school.address);
    setVal('spPhone', school.phone);
    setVal('spEmail', school.email);
    setVal('spLicense', school.license || 'LIC-2026-9941');
    setVal('spPrincipal', school.principal);
    setVal('spStages', school.stages || 'التعليم الأساسي (1-9) + الثانوي (علمي/أدبي)');
    setVal('spCapacity', school.capacity || 480);
    setVal('spLogo', school.logo || defaultLogo);
    setVal('spCampus', school.campusPhoto || defaultCampus);
}
window.renderSchoolProfile = renderSchoolProfile;

function saveSchoolProfileForm() {
    const school = getActiveSchoolEntity();
    if (!school) return;

    const getVal = (id) => document.getElementById(id)?.value?.trim() || '';
    school.name = getVal('spName') || school.name;
    school.nameEn = getVal('spNameEn') || school.nameEn;
    school.motto = getVal('spMotto') || school.motto;
    school.est = getVal('spEst') || school.est;
    school.city = getVal('spCity') || school.city;
    school.address = getVal('spAddress') || school.address;
    school.phone = getVal('spPhone') || school.phone;
    school.email = getVal('spEmail') || school.email;
    school.principal = getVal('spPrincipal') || school.principal;
    school.stages = getVal('spStages') || school.stages;
    school.capacity = parseInt(getVal('spCapacity')) || school.capacity;
    school.logo = getVal('spLogo') || school.logo;
    school.campusPhoto = getVal('spCampus') || school.campusPhoto;

    // Update active user & displays if applicable
    if (window.me && window.me.schoolId !== 'ALL') {
        window.me.schoolName = school.name;
    }
    const disp = document.getElementById('activeSchoolDisplay');
    if (disp) disp.textContent = school.name;

    renderSchoolProfile();
    if (typeof toast === 'function') toast('✅ تم حفظ وتحديث بيانات الملف التعريفي والترخيص بنجاح!');
}
window.saveSchoolProfileForm = saveSchoolProfileForm;

function renderSchoolUsersGrid() {
    const tb = document.getElementById('tbl-school-users-grid');
    if (!tb) return;

    const school = getActiveSchoolEntity();
    if (!school) return;

    const nameHeader = document.getElementById('schoolUsersCurrentName');
    if (nameHeader) nameHeader.textContent = school.name;

    const schoolCode = school.id; // e.g. SCH-01
    const schoolNum = parseInt(String(school.id).replace(/\D/g, '')) || 1;
    const schoolNumPad = String(schoolNum).padStart(2, '0');

    // Collect school users: Principal + School Employees
    const rawEmployees = (window.DB && window.DB.employees && Array.isArray(window.DB.employees)) ? window.DB.employees : [];
    
    // Filter employees belonging to this school
    const schoolEmps = rawEmployees.filter(emp => {
        return emp.schoolId === schoolCode || 
               emp.schoolId === `SCH-${schoolNumPad}` ||
               emp.code?.startsWith(`EMP-${schoolNumPad}-`) ||
               emp.id?.startsWith(`EMP-${schoolNumPad}-`) ||
               emp.schoolName === school.name;
    });

    // Also include principal from DB.users if exists
    const rawUsers = (window.DB && window.DB.users && Array.isArray(window.DB.users)) ? window.DB.users : [];
    const schoolPrincipalUser = rawUsers.find(u => {
        return (u.schoolId === schoolCode || u.schoolId === schoolNum || u.username === `admin_sch_${schoolNumPad}`) && !u.portal?.includes('saas');
    });

    const userList = [];

    // Add principal as row #1
    userList.push({
        id: schoolPrincipalUser ? schoolPrincipalUser.id : `USR-SCH-${schoolNumPad}-01`,
        username: schoolPrincipalUser ? schoolPrincipalUser.username : `admin_sch_${schoolNumPad}`,
        name: school.principal || 'مدير المدرسة المعتمد',
        role: 'school_admin',
        roleName: 'مدير المدرسة (School Admin)',
        job: 'المدير العام للمنشأة',
        dept: 'الإدارة العامة والمتابعة',
        phone: school.phone ? school.phone.split('|')[0].trim() : '770112233',
        email: school.email || `principal.${schoolNum}@edu.ye`,
        status: 'نشط 🟢',
        permissionsText: 'كافة واجهات وصلاحيات المدرسة (95 واجهة) 👑'
    });

    // Add school employees (teachers, accountants, supervisors)
    schoolEmps.forEach((emp, eIdx) => {
        // Skip if same as principal
        if (emp.name === school.principal) return;

        const isTeacher = (emp.role && emp.role.includes('معلم')) || (emp.dept && emp.dept.includes('تدريس')) || (emp.job && emp.job.includes('معلم'));
        const isAccountant = (emp.role && (emp.role.includes('محاسب') || emp.role.includes('مالي'))) || (emp.dept && emp.dept.includes('مالي'));

        let roleKey = 'staff';
        let roleName = 'كادر إداري';
        let permText = 'شؤون الموظفين والخدمات العامة';
        let defaultUsername = `staff_${schoolNumPad}_${eIdx + 1}`;

        if (isTeacher) {
            roleKey = 'teacher';
            roleName = 'معلم / عضو هيئة تدريس';
            permText = 'رصد الدرجات، التحضير، والجدول المدرسي 📚';
            defaultUsername = (eIdx === 1) ? 'teacher' : `teacher_${schoolNumPad}_${eIdx}`;
        } else if (isAccountant) {
            roleKey = 'staff';
            roleName = 'محاسب وشؤون مالية';
            permText = 'السندات، الصناديق، الرسوم، والرواتب 💼';
            defaultUsername = (eIdx === 2) ? 'staff' : `accountant_${schoolNumPad}_${eIdx}`;
        }

        userList.push({
            id: emp.id || `USR-SCH-${schoolNumPad}-${String(eIdx + 2).padStart(2, '0')}`,
            username: defaultUsername,
            name: emp.name,
            role: roleKey,
            roleName: roleName,
            job: emp.job || emp.role || roleName,
            dept: emp.dept || emp.specialization || 'الكادر المدرسي',
            phone: emp.phone || '---',
            email: emp.email || `${defaultUsername}@edu.ye`,
            status: emp.status || 'على رأس العمل 🟢',
            permissionsText: permText
        });
    });

    // Filter by search query
    const q = (document.getElementById('searchSchoolUsers')?.value || '').toLowerCase().trim();
    const roleFilter = document.getElementById('filterSchoolUserRole')?.value || 'ALL';

    const filtered = userList.filter(u => {
        if (roleFilter !== 'ALL') {
            if (roleFilter === 'principal' && u.role !== 'school_admin') return false;
            if (roleFilter === 'teacher' && u.role !== 'teacher') return false;
            if (roleFilter === 'staff' && (u.role === 'school_admin' || u.role === 'teacher')) return false;
        }
        if (!q) return true;
        const txt = [u.id, u.username, u.name, u.roleName, u.job, u.dept, u.phone, u.email].join(' ').toLowerCase();
        return txt.includes(q);
    });

    // Update KPIs
    const totalTeachers = userList.filter(u => u.role === 'teacher').length;
    const totalStaff = userList.filter(u => u.role !== 'teacher' && u.role !== 'school_admin').length;
    const activeCount = userList.filter(u => !u.status?.includes('موقوف')).length;

    const setTxt = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
    setTxt('suTotalCount', `${userList.length} مستخدم وكادر`);
    setTxt('suTeachersCount', `${totalTeachers} معلم ومعلمة`);
    setTxt('suStaffCount', `${totalStaff} إداري ومحاسب`);
    setTxt('suActiveCount', `${activeCount} مفعل 🟢`);

    // Render table
    if (filtered.length === 0) {
        tb.innerHTML = `<tr><td colspan="11" style="text-align:center;padding:24px;color:#94a3b8;"><i class="fa-solid fa-users-slash" style="font-size:1.8rem;margin-bottom:8px;display:block;color:#64748b;"></i>لا يوجد مستخدمون أو موظفون مطابقون لمعايير البحث في هذه المدرسة</td></tr>`;
        return;
    }

    tb.innerHTML = filtered.map((u, idx) => {
        let badgeColor = 'rgba(59,130,246,0.15);color:#60a5fa;border:1px solid rgba(59,130,246,0.3);';
        let icon = 'fa-user-tie';
        if (u.role === 'school_admin') {
            badgeColor = 'rgba(245,158,11,0.15);color:#fbbf24;border:1px solid rgba(245,158,11,0.3);';
            icon = 'fa-crown';
        } else if (u.role === 'teacher') {
            badgeColor = 'rgba(16,185,129,0.15);color:#34d399;border:1px solid rgba(16,185,129,0.3);';
            icon = 'fa-chalkboard-user';
        }

        return `
            <tr data-collection="employees" data-id="${u.id}" ondblclick="openForm('school_user', '${u.id}')" title="انقر مرتين لتعديل الصلاحيات (${u.name})" style="cursor:pointer;">
                <td style="font-weight:700;color:#94a3b8;text-align:center;">${idx + 1}</td>
                <td style="font-family:monospace;color:#38bdf8;font-weight:700;"><i class="fa-solid fa-hashtag" style="font-size:0.75rem;"></i> ${u.id}</td>
                <td style="font-family:monospace;color:#60a5fa;font-weight:800;"><i class="fa-solid fa-id-badge" style="font-size:0.75rem;"></i> ${u.username}</td>
                <td style="font-weight:800;color:#f8fafc;"><strong style="font-size:0.92rem;">${u.name}</strong></td>
                <td><span class="badge" style="background:${badgeColor}font-weight:700;"><i class="fa-solid ${icon}"></i> ${u.roleName}</span></td>
                <td style="color:#cbd5e1;font-size:0.85rem;"><i class="fa-solid fa-briefcase" style="font-size:0.75rem;color:#64748b;margin-left:4px;"></i> ${u.dept}</td>
                <td style="font-family:monospace;color:#38bdf8;"><i class="fa-solid fa-phone" style="font-size:0.75rem;"></i> ${u.phone}</td>
                <td style="color:#94a3b8;font-size:0.82rem;"><i class="fa-solid fa-envelope" style="font-size:0.75rem;"></i> ${u.email}</td>
                <td><span class="badge badge-success"><i class="fa-solid fa-circle-dot"></i> ${u.status}</span></td>
                <td><span class="badge badge-info" style="font-size:0.75rem;"><i class="fa-solid fa-shield-halved"></i> ${u.permissionsText}</span></td>
                <td style="text-align:center;">
                    <div style="display:flex;gap:4px;justify-content:center;">
                        <button type="button" class="btn-action edit" onclick="event.stopPropagation();openForm('school_user', '${u.id}')" title="تعديل"><i class="fa-solid fa-pen-to-square"></i></button>
                        <button type="button" class="btn-action view" onclick="event.stopPropagation();viewRowDetails('employees', '${u.id}')" title="استعراض"><i class="fa-solid fa-eye"></i></button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}
window.renderSchoolUsersGrid = renderSchoolUsersGrid;


// ============================================================================
// UNIVERSAL FIELD POLICY ENGINE (محرك سياسات الحقول والقواعد الإلزامية والمحمية)
// ============================================================================
window.UniversalFieldPolicyEngine = {
    // 1. Immutable & Read-only Policy Keys
    immutableKeys: [
        'id', 'code', 'studentId', 'empId', 'userId', 'nationalId', 'license', 'licenseNo',
        'voucherNo', 'receiptNo', 'checkNo', 'academicYear', 'createdAt', 'createdBy',
        'hash', 'blockchainHash', 'txHash', 'created_at', 'updated_at',
        'totalAmount', 'remainingBalance', 'totalTuition', 'vatAmount', 'netSalary'
    ],

    // 2. Attach live validation to any form container
    attachToContainer: function(container) {
        if (!container) return;
        const inputs = container.querySelectorAll('input, select, textarea');
        inputs.forEach(input => {
            // Live validation on blur
            input.addEventListener('blur', () => this.validateField(input));
            
            // Clear errors on input
            input.addEventListener('input', () => {
                if (input.classList.contains('is-invalid')) {
                    this.validateField(input, true);
                }
            });

            // Protect read-only fields against keyboard editing
            if (input.readOnly || input.disabled || input.dataset.readonly === '1') {
                input.addEventListener('keydown', (e) => {
                    if (!['Tab', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) {
                        e.preventDefault();
                    }
                });
            }
        });
    },

    // 3. Validate a single input field
    validateField: function(input, isTyping = false) {
        if (!input) return true;
        if (input.readOnly || input.disabled || input.dataset.readonly === '1') return true;

        const isRequired = input.required || input.dataset.required === '1' || input.getAttribute('aria-required') === 'true';
        let val = (input.value || '').trim();

        // Normalize Arabic digits
        val = val.replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));

        let errEl = input.parentElement.querySelector('.field-error-msg');

        // Required check
        if (isRequired && !val) {
            if (!isTyping) {
                input.classList.add('is-invalid');
                input.classList.remove('is-valid');
                if (!errEl) {
                    errEl = document.createElement('span');
                    errEl.className = 'field-error-msg';
                    input.parentElement.appendChild(errEl);
                }
                const name = input.dataset.fieldName || input.placeholder || 'هذا الحقل';
                errEl.innerHTML = `<i class="fa-solid fa-circle-exclamation"></i> (${name}) إجباري ولا يمكن تركه فارغاً`;
            }
            return false;
        }

        // Phone pattern check
        const isPhone = input.type === 'tel' || (input.id && input.id.toLowerCase().includes('phone')) || (input.dataset.key && input.dataset.key.toLowerCase().includes('phone'));
        if (isPhone && val) {
            const cleanPhone = val.replace(/[\s\-\+]/g, '');
            const yemenPhoneRegex = /^(?:(?:967)|0)?(7[01378][0-9]{7})$/;
            if (!yemenPhoneRegex.test(cleanPhone)) {
                if (!isTyping) {
                    input.classList.add('is-invalid');
                    input.classList.remove('is-valid');
                    if (!errEl) {
                        errEl = document.createElement('span');
                        errEl.className = 'field-error-msg';
                        input.parentElement.appendChild(errEl);
                    }
                    errEl.innerHTML = `<i class="fa-solid fa-triangle-exclamation"></i> رقم هاتف غير صالح (مثال: 777123456)`;
                }
                return false;
            }
        }

        // Amount / Numeric check
        const isNum = input.type === 'number' || (input.dataset.key && (input.dataset.key.includes('fee') || input.dataset.key.includes('salary') || input.dataset.key.includes('amount')));
        if (isNum && val) {
            const n = parseFloat(val);
            if (isNaN(n) || n < 0) {
                if (!isTyping) {
                    input.classList.add('is-invalid');
                    input.classList.remove('is-valid');
                    if (!errEl) {
                        errEl = document.createElement('span');
                        errEl.className = 'field-error-msg';
                        input.parentElement.appendChild(errEl);
                    }
                    errEl.innerHTML = `<i class="fa-solid fa-triangle-exclamation"></i> يجب إدخال قيمة عددية موجبة صالحة`;
                }
                return false;
            }
        }

        // If valid
        input.classList.remove('is-invalid');
        if (val) input.classList.add('is-valid');
        if (errEl) errEl.remove();
        return true;
    },

    // 4. Auto-initialize across document on DOM ready
    init: function() {
        document.querySelectorAll('form').forEach(f => this.attachToContainer(f));
        document.querySelectorAll('.page-view').forEach(p => this.attachToContainer(p));
    }
};

// Auto-run policy engine on DOM content loaded and interval checks
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => window.UniversalFieldPolicyEngine.init());
} else {
    window.UniversalFieldPolicyEngine.init();
}

